INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VLn6vLYLazq', 4, '{"title":"13","description":"<p>13、病大温，发热头晕，目眩，齿枯，唇焦，谵语，不省人事，面色乍青乍赤，脉急大而数者，$f{大黄香蒲汤}主之；若喉闭难下咽者，针少商令出血；若脉乍疏乍数，目内陷者，死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000813,"note":"","videoMemo":"","fangList":["大黄香蒲汤"],"bieMing":""}}', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '2024-12-07T08:31:44.000Z', '13、病大温，发热头晕，目眩，齿枯，唇焦，谵语，不省人事，面色乍青乍赤，脉急大而数者，$f{大黄香蒲汤}主之；若喉闭难下咽者，针少商令出血；若脉乍疏乍数，目内陷者，死。', '2024-12-07T08:31:44.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('grjC3zHTuhb', 4, '{"title":"14","description":"<p>14、温病，下之大便溏，当自愈；若下之利不止者，必腹满，宜$f{茯苓白术甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000814,"note":"","videoMemo":"","fangList":["茯苓白术甘草汤"],"bieMing":""}}', '2024-12-07T08:59:09.000Z', '2024-12-07T08:59:09.000Z', '2024-12-07T08:59:09.000Z', '14、温病，下之大便溏，当自愈；若下之利不止者，必腹满，宜$f{茯苓白术甘草汤}主之。', '2024-12-07T08:59:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g5q7wZJ3rFx', 4, '{"title":"15、风温者，因其人素有热，更伤于风，而为病也","description":"<p>15、风温者，因其人素有热，更伤于风，而为病也。脉浮弦而数，若头不痛者，$f{桂枝去桂加黄芩牡丹汤}主之。若伏气病温，误发其汗，则大热烦冤，唇焦，目赤，或衄，或吐，耳聋，脉大而数者，宜$f{白虎汤}；大实者，宜$n{承气}辈；若至十余日则入于里，宜$f{黄连阿胶汤}。何以知其入里？以脉沉而数，心烦不卧，故知也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000815,"note":"","videoMemo":"","fangList":["桂枝去桂加黄芩牡丹汤","白虎汤","黄连阿胶汤"],"bieMing":""}}', '2024-12-07T08:59:09.000Z', '2024-12-07T08:59:09.000Z', '2024-12-07T08:59:09.000Z', '15、风温者，因其人素有热，更伤于风，而为病也。脉浮弦而数，若头不痛者，$f{桂枝去桂加黄芩牡丹汤}主之。若伏气病温，误发其汗，则大热烦冤，唇焦，目赤，或衄，或吐，耳聋，脉大而数者，宜$f{白虎汤}；大实者，宜$n{承气}辈；若至十余日则入于里，宜$f{黄连阿胶汤}。何以知其入里？以脉沉而数，心烦不卧，故知也。', '2024-12-07T08:59:09.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3TVUwUTTyUu', 4, '{"title":"16","description":"<p>16、病温，治不得法，留久移于三焦，其在上焦，则舌蹇，神昏，宜$f{栀子汤}；其在中焦，则腹痛而利，利后腹痛，唇口干燥，宜$f{白虎加地黄汤}；其在下焦，从腰以下热，齿黑，咽干，宜$f{百合地黄牡丹皮半夏茯苓汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000816,"note":"","videoMemo":"","fangList":["栀子汤","白虎加地黄汤","百合地黄牡丹皮半夏茯苓汤"],"bieMing":""}}', '2024-12-07T09:10:19.000Z', '2024-12-07T09:10:19.000Z', '2024-12-07T09:10:19.000Z', '16、病温，治不得法，留久移于三焦，其在上焦，则舌蹇，神昏，宜$f{栀子汤}；其在中焦，则腹痛而利，利后腹痛，唇口干燥，宜$f{白虎加地黄汤}；其在下焦，从腰以下热，齿黑，咽干，宜$f{百合地黄牡丹皮半夏茯苓汤}。', '2024-12-07T09:10:19.000Z', 1, NULL, '5IGM9t76quT', 'section', 'GyqBRPJNca3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hSjH4No7crJ', 4, '{"title":"1","description":"<p>1、伤暑肺先受之，肺为气府，暑伤元气，寸口脉弱，口渴，汗出，神昏，气短，$f{竹叶石膏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000901,"note":"","videoMemo":"","fangList":["竹叶石膏汤"],"bieMing":""}}', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '1、伤暑肺先受之，肺为气府，暑伤元气，寸口脉弱，口渴，汗出，神昏，气短，$f{竹叶石膏汤}主之。', '2024-12-07T09:33:06.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ryP9Dt6YD1C', 4, '{"title":"2","description":"<p>2、伤暑，发热，汗出，口渴，脉浮而大，名曰中暍，$f{白虎加人参黄连阿胶汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000902,"note":"","videoMemo":"","fangList":["白虎加人参黄连阿胶汤"],"bieMing":""}}', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2、伤暑，发热，汗出，口渴，脉浮而大，名曰中暍，$f{白虎加人参黄连阿胶汤}主之。', '2024-12-07T09:33:06.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2VrLNgnIV1Q', 4, '{"title":"3","description":"<p>3、伤暑，汗出已，发热，烦躁，声嘶，脉反浮数者，此为肺液伤，$f{百合地黄加牡蛎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000903,"note":"","videoMemo":"","fangList":["百合地黄加牡蛎汤"],"bieMing":""}}', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '3、伤暑，汗出已，发热，烦躁，声嘶，脉反浮数者，此为肺液伤，$f{百合地黄加牡蛎汤}主之。', '2024-12-07T09:33:06.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('srjQJgc9TxP', 4, '{"title":"4","description":"<p>4、伤暑，心下有水气，汗出，咳嗽，渴欲饮水，水入则吐，脉弱而滑，$f{栝蒌茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000904,"note":"","videoMemo":"","fangList":["栝蒌茯苓汤"],"bieMing":""}}', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '4、伤暑，心下有水气，汗出，咳嗽，渴欲饮水，水入则吐，脉弱而滑，$f{栝蒌茯苓汤}主之。', '2024-12-07T09:33:06.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DnE55beoXTk', 4, '{"title":"5","description":"<p>5、伤暑，发热，无汗，水行皮中故也，脉必浮而滑，先以热水灌之，令汗出，后以$f{竹茹半夏汤}与之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000905,"note":"","videoMemo":"","fangList":["竹茹半夏汤"],"bieMing":""}}', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '5、伤暑，发热，无汗，水行皮中故也，脉必浮而滑，先以热水灌之，令汗出，后以$f{竹茹半夏汤}与之。', '2024-12-07T09:33:06.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LzLKUGxqxmB', 4, '{"title":"6、太阳中热者，暍是也","description":"<p>6、太阳中热者，暍是也。其人汗出，恶寒，身热而渴，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000906,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '2024-12-07T09:33:06.000Z', '6、太阳中热者，暍是也。其人汗出，恶寒，身热而渴，$f{白虎加人参汤}主之。', '2024-12-07T09:33:06.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NUWn6KdvhVt', 4, '{"title":"7","description":"<p>7、太阳中暍，身热，疼重，而脉微弱者，以夏月伤冷水，水行皮中所致也，$f{猪苓加人参汤}主之；一物$f{瓜蒂汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000907,"note":"","videoMemo":"","fangList":["猪苓加人参汤","瓜蒂汤"],"bieMing":""}}', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '7、太阳中暍，身热，疼重，而脉微弱者，以夏月伤冷水，水行皮中所致也，$f{猪苓加人参汤}主之；一物$f{瓜蒂汤}亦主之。', '2024-12-09T01:15:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7C1nnPnCT8J', 4, '{"title":"8","description":"<p>8、凡病暑者，当汗出，不汗出者，必发热，发热者，必不汗出也，不可发汗，发汗则发热，烦躁，失声，此为肺液枯，息高气贲者，不治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '8、凡病暑者，当汗出，不汗出者，必发热，发热者，必不汗出也，不可发汗，发汗则发热，烦躁，失声，此为肺液枯，息高气贲者，不治。', '2024-12-09T01:15:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fnQMOYzc8u0', 4, '{"title":"9","description":"<p>9、伤暑，夜卧不安，烦躁，谵语，舌赤，脉数，此为暑邪干心也，$f{黄连半夏石膏甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000909,"note":"","videoMemo":"","fangList":["黄连半夏石膏甘草汤"],"bieMing":""}}', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '9、伤暑，夜卧不安，烦躁，谵语，舌赤，脉数，此为暑邪干心也，$f{黄连半夏石膏甘草汤}主之。', '2024-12-09T01:15:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4QieeaYLRed', 4, '{"title":"10","description":"<p>10、太阳中暍，发热，恶寒，身重疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷；小有劳身即热；口开，前板齿燥；若发汗，则恶寒甚；加温针，则发热甚，数下之，则淋甚；$f{白虎加桂枝人参芍药汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000910,"note":"","videoMemo":"","fangList":["白虎加桂枝人参芍药汤"],"bieMing":""}}', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '10、太阳中暍，发热，恶寒，身重疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷；小有劳身即热；口开，前板齿燥；若发汗，则恶寒甚；加温针，则发热甚，数下之，则淋甚；$f{白虎加桂枝人参芍药汤}主之。', '2024-12-09T01:15:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5G9j2S81JLO', 4, '{"title":"11","description":"<p>11、伤暑，脉弱，口渴，大汗出，头晕者，$f{人参石膏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000911,"note":"","videoMemo":"","fangList":["人参石膏汤"],"bieMing":""}}', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '11、伤暑，脉弱，口渴，大汗出，头晕者，$f{人参石膏汤}主之。', '2024-12-09T01:15:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I30ZSG8hmnh', 4, '{"title":"12、伤暑者，头不痛，头痛者风也，头重者湿也","description":"<p>12、伤暑者，头不痛，头痛者风也，头重者湿也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001000912,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '2024-12-09T01:15:33.000Z', '12、伤暑者，头不痛，头痛者风也，头重者湿也。', '2024-12-09T01:15:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'V3oXNm4Y5uu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AJwVEMprElT', 4, '{"title":"1、热之为病，有外至，有内生","description":"<p>1、热之为病，有外至，有内生。外至可移，内有定处，不循经序，舍于所合，与温相似，根本异源，传经化热，伏气变温，医多不晓，认为一体，如此杀人，莫可穷极。为子条记，传与后贤。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '1、热之为病，有外至，有内生。外至可移，内有定处，不循经序，舍于所合，与温相似，根本异源，传经化热，伏气变温，医多不晓，认为一体，如此杀人，莫可穷极。为子条记，传与后贤。', '2024-12-09T01:36:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'IME7cq10zI4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DDtP68oT64Q', 4, '{"title":"2","description":"<p>2、热病，面赤，口烂，心中痛，欲呕，脉洪而数，此热邪干心也，$f{黄连黄芩泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001002,"note":"","videoMemo":"","fangList":["黄连黄芩泻心汤"],"bieMing":""}}', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2、热病，面赤，口烂，心中痛，欲呕，脉洪而数，此热邪干心也，$f{黄连黄芩泻心汤}主之。', '2024-12-09T01:36:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'IME7cq10zI4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KSx8prTY6hm', 4, '{"title":"3","description":"<p>3、热病，身热，左胁痛，甚则狂言乱语，脉弦而数，此热邪乘肝也，$f{黄连黄芩半夏猪胆汁汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001003,"note":"","videoMemo":"","fangList":["黄连黄芩半夏猪胆汁汤"],"bieMing":""}}', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '3、热病，身热，左胁痛，甚则狂言乱语，脉弦而数，此热邪乘肝也，$f{黄连黄芩半夏猪胆汁汤}主之。', '2024-12-09T01:36:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'IME7cq10zI4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3LiN4lPU0PL', 4, '{"title":"4","description":"<p>4、热病，腹中痛，不可按，不能俯仰，大便难，脉数而大，此热邪乘脾也，$f{大黄厚朴甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001004,"note":"","videoMemo":"","fangList":["大黄厚朴甘草汤"],"bieMing":""}}', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '4、热病，腹中痛，不可按，不能俯仰，大便难，脉数而大，此热邪乘脾也，$f{大黄厚朴甘草汤}主之。', '2024-12-09T01:36:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'IME7cq10zI4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('elEw7vc776m', 4, '{"title":"5","description":"<p>5、热病，口渴，喘，嗽，痛引胸中，不得太息，脉短而数，此热邪乘肺也，$f{黄连石膏半夏甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001005,"note":"","videoMemo":"","fangList":["黄连石膏半夏甘草汤"],"bieMing":""}}', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '5、热病，口渴，喘，嗽，痛引胸中，不得太息，脉短而数，此热邪乘肺也，$f{黄连石膏半夏甘草汤}主之。', '2024-12-09T01:36:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'IME7cq10zI4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bVO3MmaQaXk', 4, '{"title":"6","description":"<p>6、热病，咽中干，腰痛，足热，脉沉而数，此热邪移肾也，$f{地黄黄柏黄连半夏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001006,"note":"","videoMemo":"","fangList":["地黄黄柏黄连半夏汤"],"bieMing":""}}', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '2024-12-09T01:36:48.000Z', '6、热病，咽中干，腰痛，足热，脉沉而数，此热邪移肾也，$f{地黄黄柏黄连半夏汤}主之。', '2024-12-09T01:36:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'IME7cq10zI4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hnwAJg2S3ek', 4, '{"title":"1","description":"<p>1、湿气为病，内外上下，四处流行，随邪变化，各具病形，按法诊治，勿失纪纲。湿气在上，中于雾露，头痛，项强，两额疼痛，脉浮而涩者，$f{黄芪桂枝茯苓细辛汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001101,"note":"","videoMemo":"","fangList":["黄芪桂枝茯苓细辛汤"],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '1、湿气为病，内外上下，四处流行，随邪变化，各具病形，按法诊治，勿失纪纲。湿气在上，中于雾露，头痛，项强，两额疼痛，脉浮而涩者，$f{黄芪桂枝茯苓细辛汤}主之。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1i1vhuiz47o', 4, '{"title":"2","description":"<p>2、湿气在下，中于水冷，从腰以下重，两足肿，脉沉而涩者，$f{桂枝茯苓白术细辛汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001102,"note":"","videoMemo":"","fangList":["桂枝茯苓白术细辛汤"],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2、湿气在下，中于水冷，从腰以下重，两足肿，脉沉而涩者，$f{桂枝茯苓白术细辛汤}主之。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yX7yeKjoePP', 4, '{"title":"3","description":"<p>3、湿气在外，因风相搏，流于经络，骨节烦疼，卧不欲食，脉浮缓，按之涩，$f{桂枝汤}微发其汗，令风湿俱去；若恶寒，身体疼痛，四肢不仁，脉浮而细紧，此为寒气，并$f{桂枝麻黄各半汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001103,"note":"","videoMemo":"","fangList":["桂枝汤","桂枝麻黄各半汤"],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '3、湿气在外，因风相搏，流于经络，骨节烦疼，卧不欲食，脉浮缓，按之涩，$f{桂枝汤}微发其汗，令风湿俱去；若恶寒，身体疼痛，四肢不仁，脉浮而细紧，此为寒气，并$f{桂枝麻黄各半汤}主之。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JEtvIXei0dh', 4, '{"title":"4、湿气在内，与脾相搏，发为中满；胃寒相将，变为泄泻","description":"<p>4、湿气在内，与脾相搏，发为中满；胃寒相将，变为泄泻。中满宜$f{白术茯苓厚朴汤}；泄泻宜$f{理中汤}；若上干肺，发为肺寒，宜$f{小青龙汤}；下移肾，发为淋漓，宜$f{五苓散}；流于肌肉，发为黄肿，宜$f{麻黄茯苓汤}；若流于经络，与热气相乘，则发痈脓；脾胃素寒，与湿久留，发为水饮，与燥相搏，发为痰饮，治属饮家。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001104,"note":"","videoMemo":"","fangList":["白术茯苓厚朴汤","理中汤","小青龙汤","五苓散","麻黄茯苓汤"],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '4、湿气在内，与脾相搏，发为中满；胃寒相将，变为泄泻。中满宜$f{白术茯苓厚朴汤}；泄泻宜$f{理中汤}；若上干肺，发为肺寒，宜$f{小青龙汤}；下移肾，发为淋漓，宜$f{五苓散}；流于肌肉，发为黄肿，宜$f{麻黄茯苓汤}；若流于经络，与热气相乘，则发痈脓；脾胃素寒，与湿久留，发为水饮，与燥相搏，发为痰饮，治属饮家。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2t3yJvFCNS8', 4, '{"title":"5","description":"<p>5、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹；湿痹之候，其人小便不利，大便反快，但当利其小便。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001105,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '5、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹；湿痹之候，其人小便不利，大便反快，但当利其小便。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3UnzqbCE328', 4, '{"title":"6、湿家之为病，一身尽疼，发热，身色如熏黄","description":"<p>6、湿家之为病，一身尽疼，发热，身色如熏黄。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001106,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '6、湿家之为病，一身尽疼，发热，身色如熏黄。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a62B9TwRmz4', 4, '{"title":"7","description":"<p>7、湿家，其人但头汗出，背强，欲得被覆向火，若下之早，则哕，胸满，小便不利，舌上滑苔者，以丹田有热，胸中有寒，渴欲得水，而不能饮，口燥烦也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001107,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '7、湿家，其人但头汗出，背强，欲得被覆向火，若下之早，则哕，胸满，小便不利，舌上滑苔者，以丹田有热，胸中有寒，渴欲得水，而不能饮，口燥烦也。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z7bBwTh3tUI', 4, '{"title":"8、湿家下之，额上汗出，微喘，小便利者死；若下利不止者亦死","description":"<p>8、湿家下之，额上汗出，微喘，小便利者死；若下利不止者亦死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001108,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '8、湿家下之，额上汗出，微喘，小便利者死；若下利不止者亦死。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uiG3yei4qYL', 4, '{"title":"9","description":"<p>9、问曰：风湿相搏，一身尽疼，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者何也？</p>\n<p></p>\n<p>     师曰：发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，发其汗，但微微似欲汗出者，风湿俱去也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001109,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '9、问曰：风湿相搏，一身尽疼，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者何也？ 师曰：发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，发其汗，但微微似欲汗出者，风湿俱去也。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9RbKHn5SqTH', 4, '{"title":"10","description":"<p>10、湿家病，身上尽疼痛，发热，面黄而喘，头痛，鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故$f{鼻塞}，纳药鼻中，则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001110,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '2024-12-09T02:12:22.000Z', '10、湿家病，身上尽疼痛，发热，面黄而喘，头痛，鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故$f{鼻塞}，纳药鼻中，则愈。', '2024-12-09T02:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('riwfNQ1y2PU', 4, '{"title":"11","description":"<p>11、湿家，身烦疼，可与$f{麻黄加术汤}发其汗为宜，慎不可以火攻之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001111,"note":"","videoMemo":"","fangList":["麻黄加术汤"],"bieMing":""}}', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '11、湿家，身烦疼，可与$f{麻黄加术汤}发其汗为宜，慎不可以火攻之。', '2024-12-09T02:48:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VtQJcPnt4IC', 4, '{"title":"12、病者一身尽疼，发热，日晡所剧者，此名风湿","description":"<p>12、病者一身尽疼，发热，日晡所剧者，此名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001112,"note":"","videoMemo":"","fangList":["麻黄杏仁薏苡甘草汤"],"bieMing":""}}', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '12、病者一身尽疼，发热，日晡所剧者，此名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。', '2024-12-09T02:48:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A41qKz90XjF', 4, '{"title":"13","description":"<p>13、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001113,"note":"","videoMemo":"","fangList":["防己黄芪汤"],"bieMing":""}}', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '13、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。', '2024-12-09T02:48:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OpssnWqcXWD', 4, '{"title":"14","description":"<p>14、伤寒八九日，风湿相搏，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{白术附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001114,"note":"","videoMemo":"","fangList":["桂枝附子汤","白术附子汤"],"bieMing":""}}', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '14、伤寒八九日，风湿相搏，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{白术附子汤}主之。', '2024-12-09T02:48:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1WETnf3KxN9', 4, '{"title":"15","description":"<p>15、风湿相搏，骨节疼烦，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风，不欲去衣，或身微肿者，$f{甘草附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001115,"note":"","videoMemo":"","fangList":["甘草附子汤"],"bieMing":""}}', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '2024-12-09T02:48:48.000Z', '15、风湿相搏，骨节疼烦，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风，不欲去衣，或身微肿者，$f{甘草附子汤}主之。', '2024-12-09T02:48:48.000Z', 1, NULL, '5IGM9t76quT', 'section', 'mN0iZDj3yl7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jebFl6C2wvv', 4, '{"title":"1","description":"<p>1、伤燥，肺先受之，出则大肠受之，移传五脏，病各异形，分别诊治，消息脉经。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '1、伤燥，肺先受之，出则大肠受之，移传五脏，病各异形，分别诊治，消息脉经。', '2024-12-09T03:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'B72k8bHIXIB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZQ8d73tQ7Nd', 4, '{"title":"2","description":"<p>2、燥病，口渴，咽干，喘，咳，胸满痛甚则唾血，脉浮短而急，此燥邪干肺也，$f{竹叶石膏杏子甘草汤}主之；若移于大肠，则大便难，口渴，欲饮热，脉急大，在下者，$f{麻仁白蜜煎}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001202,"note":"","videoMemo":"","fangList":["竹叶石膏杏子甘草汤","麻仁白蜜煎"],"bieMing":""}}', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2、燥病，口渴，咽干，喘，咳，胸满痛甚则唾血，脉浮短而急，此燥邪干肺也，$f{竹叶石膏杏子甘草汤}主之；若移于大肠，则大便难，口渴，欲饮热，脉急大，在下者，$f{麻仁白蜜煎}主之。', '2024-12-09T03:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'B72k8bHIXIB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('76iiFaevp5l', 4, '{"title":"3","description":"<p>3、燥病，口烂，气上逆，胸中痛，脉大而涩，此燥邪乘心也，$f{栀子连翘甘草栝蒌汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001203,"note":"","videoMemo":"","fangList":["栀子连翘甘草栝蒌汤"],"bieMing":""}}', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '3、燥病，口烂，气上逆，胸中痛，脉大而涩，此燥邪乘心也，$f{栀子连翘甘草栝蒌汤}主之。', '2024-12-09T03:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'B72k8bHIXIB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lt3Q6MhDtzh', 4, '{"title":"4","description":"<p>4、燥病，目赤，困苦，咽干，胁下痛，脉弦而数，此燥邪乘肝也，$f{黄芩牡丹皮栝蒌半夏枳实汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001204,"note":"","videoMemo":"","fangList":["黄芩牡丹皮栝蒌半夏枳实汤"],"bieMing":""}}', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '4、燥病，目赤，困苦，咽干，胁下痛，脉弦而数，此燥邪乘肝也，$f{黄芩牡丹皮栝蒌半夏枳实汤}主之。', '2024-12-09T03:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'B72k8bHIXIB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Spy7jQPZ0XK', 4, '{"title":"5","description":"<p>5、燥病，色黄，腹中痛不可按，大便难，脉数而滑，此燥邪乘脾也，$f{白虎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001205,"note":"","videoMemo":"","fangList":["白虎汤"],"bieMing":""}}', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '5、燥病，色黄，腹中痛不可按，大便难，脉数而滑，此燥邪乘脾也，$f{白虎汤}主之。', '2024-12-09T03:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'B72k8bHIXIB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4c8boBLr9rJ', 4, '{"title":"6","description":"<p>6、燥病，咽干，喉痛，少腹急痛，小便赤，脉沉而急，此燥邪移肾也，$f{地黄黄柏茯苓栝蒌汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001206,"note":"","videoMemo":"","fangList":["地黄黄柏茯苓栝蒌汤"],"bieMing":""}}', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '2024-12-09T03:12:22.000Z', '6、燥病，咽干，喉痛，少腹急痛，小便赤，脉沉而急，此燥邪移肾也，$f{地黄黄柏茯苓栝蒌汤}主之。', '2024-12-09T03:12:22.000Z', 1, NULL, '5IGM9t76quT', 'section', 'B72k8bHIXIB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T5hT4io2LE1', 4, '{"title":"1","description":"<p>1、风为百病之长，中于面，则下阳明，甚则入脾；中于项，则下太阳，甚则入肾；中于侧，则下少阳，甚则入肝；病变不一，慎毋失焉。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '1、风为百病之长，中于面，则下阳明，甚则入脾；中于项，则下太阳，甚则入肾；中于侧，则下少阳，甚则入肝；病变不一，慎毋失焉。', '2024-12-09T03:51:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'CdcX5CUj52l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w17Pz0CLURp', 4, '{"title":"2","description":"<p>2、风病，头痛，多汗，恶风，腋下痛，不可转侧，脉浮弦而数，此风邪干肝也，$f{小柴胡汤}主之；若流于腑，则困苦，呕逆，腹胀，善太息，$f{柴胡枳实芍药甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001302,"note":"","videoMemo":"","fangList":["小柴胡汤","柴胡枳实芍药甘草汤"],"bieMing":""}}', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2、风病，头痛，多汗，恶风，腋下痛，不可转侧，脉浮弦而数，此风邪干肝也，$f{小柴胡汤}主之；若流于腑，则困苦，呕逆，腹胀，善太息，$f{柴胡枳实芍药甘草汤}主之。', '2024-12-09T03:51:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'CdcX5CUj52l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vpGPWt6Wt36', 4, '{"title":"3","description":"<p>3、风病，胸中痛，胁支满，膺背肩胛间痛，嗌干，善噫，咽肿，喉痹，脉浮洪而数，此风邪乘心也，$f{黄连黄芩麦冬桔梗甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001303,"note":"","videoMemo":"","fangList":["黄连黄芩麦冬桔梗甘草汤"],"bieMing":""}}', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '3、风病，胸中痛，胁支满，膺背肩胛间痛，嗌干，善噫，咽肿，喉痹，脉浮洪而数，此风邪乘心也，$f{黄连黄芩麦冬桔梗甘草汤}主之。', '2024-12-09T03:51:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'CdcX5CUj52l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vW6qVLQYuvj', 4, '{"title":"4","description":"<p>4、风病，四肢懈惰，体重，不能胜衣，胁下痛引肩背，脉浮而弦涩，此风邪乘脾也，$f{桂枝去桂加茯苓白术汤}主之；若流于腑，则腹满而胀，不嗜食，枳实厚朴白术甘草汤主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001304,"note":"","videoMemo":"","fangList":["桂枝去桂加茯苓白术汤","枳实厚朴白术甘草汤"],"bieMing":""}}', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '4、风病，四肢懈惰，体重，不能胜衣，胁下痛引肩背，脉浮而弦涩，此风邪乘脾也，$f{桂枝去桂加茯苓白术汤}主之；若流于腑，则腹满而胀，不嗜食，枳实厚朴白术甘草汤主之。', '2024-12-09T03:51:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'CdcX5CUj52l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hTl403PdN1n', 4, '{"title":"5","description":"<p>5、风病，咳而喘息有音，甚则唾血，嗌干，肩背痛，脉浮弦而数，此风邪乘肺也，$f{桔梗甘草枳实芍药汤}主之；若流于大肠，则大便燥结，或下血，桔梗甘草枳实芍药加地黄牡丹汤主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001305,"note":"","videoMemo":"","fangList":["桔梗甘草枳实芍药汤","桔梗甘草枳实芍药加地黄牡丹汤"],"bieMing":""}}', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '5、风病，咳而喘息有音，甚则唾血，嗌干，肩背痛，脉浮弦而数，此风邪乘肺也，$f{桔梗甘草枳实芍药汤}主之；若流于大肠，则大便燥结，或下血，桔梗甘草枳实芍药加地黄牡丹汤主之。', '2024-12-09T03:51:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'CdcX5CUj52l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1sUEQlgC4Y9', 4, '{"title":"6","description":"<p>6、风病，面目浮肿，脊痛不能正立，隐曲不利，甚则骨痿，脉沉而弦，此风邪乘肾也，$f{柴胡桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001306,"note":"","videoMemo":"","fangList":["柴胡桂枝汤"],"bieMing":""}}', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '2024-12-09T03:51:36.000Z', '6、风病，面目浮肿，脊痛不能正立，隐曲不利，甚则骨痿，脉沉而弦，此风邪乘肾也，$f{柴胡桂枝汤}主之。', '2024-12-09T03:51:36.000Z', 1, NULL, '5IGM9t76quT', 'section', 'CdcX5CUj52l');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YfIGSoB30ny', 4, '{"title":"1","description":"<p>1、寒之为病，肾先受之，其客于五脏之间，脉引而痛；若客于八虚之室，则恶血住留，积久不去，变而成着，可不慎焉！</p>\n<p></p>\n<p>    寒病，骨痛，阴痹，腹胀，腰痛，大便难，肩背颈项引痛，脉沉而迟，此寒邪干肾也，$f{桂枝加葛根汤}主之；其着也则两腘痛，$f{甘草干姜茯苓白术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001401,"note":"","videoMemo":"","fangList":["桂枝加葛根汤","甘草干姜茯苓白术汤"],"bieMing":""}}', '2024-12-09T05:57:32.000Z', '2024-12-09T05:57:32.000Z', '2024-12-09T05:57:32.000Z', '1、寒之为病，肾先受之，其客于五脏之间，脉引而痛；若客于八虚之室，则恶血住留，积久不去，变而成着，可不慎焉！ 寒病，骨痛，阴痹，腹胀，腰痛，大便难，肩背颈项引痛，脉沉而迟，此寒邪干肾也，$f{桂枝加葛根汤}主之；其着也则两腘痛，$f{甘草干姜茯苓白术汤}主之。', '2024-12-09T05:57:32.000Z', 1, NULL, '5IGM9t76quT', 'section', 'M43hMFfNOo1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4vEqoPYXgUg', 4, '{"title":"2","description":"<p>2、寒病，两胁中痛，寒中行善掣节，逆则头痛，耳聋，脉弦而沉迟，此寒邪乘肝也，$f{小柴胡汤}主之；其着也，则两腋急痛，不能转侧，$f{柴胡黄芩芍药半夏甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001402,"note":"","videoMemo":"","fangList":["小柴胡汤","柴胡黄芩芍药半夏甘草汤"],"bieMing":""}}', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '2、寒病，两胁中痛，寒中行善掣节，逆则头痛，耳聋，脉弦而沉迟，此寒邪乘肝也，$f{小柴胡汤}主之；其着也，则两腋急痛，不能转侧，$f{柴胡黄芩芍药半夏甘草汤}主之。', '2024-12-09T08:06:58.000Z', 1, NULL, '5IGM9t76quT', 'section', 'M43hMFfNOo1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zOWdPMCXkU2', 4, '{"title":"3","description":"<p>3、寒病，胸胁支满，膺背肩胛间痛，甚则喜悲，时发眩，仆而不知人，此寒邪乘心也，$f{通脉四逆汤}主之；其着也，则肘外痛，臂不能伸，$f{甘草泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001403,"note":"","videoMemo":"","fangList":["通脉四逆汤","甘草泻心汤"],"bieMing":""}}', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '3、寒病，胸胁支满，膺背肩胛间痛，甚则喜悲，时发眩，仆而不知人，此寒邪乘心也，$f{通脉四逆汤}主之；其着也，则肘外痛，臂不能伸，$f{甘草泻心汤}主之。', '2024-12-09T08:06:58.000Z', 1, NULL, '5IGM9t76quT', 'section', 'M43hMFfNOo1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9THgaR2Crgg', 4, '{"title":"4","description":"<p>4、寒病，腹满肠鸣，食不化，飧泄，甚则足痿不收，脉迟而涩，此寒邪乘脾也，$f{理中汤}主之；其着也，则髀枢强痛，不能屈伸，$f{枳实白术茯苓甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001404,"note":"","videoMemo":"","fangList":["理中汤","枳实白术茯苓甘草汤"],"bieMing":""}}', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '4、寒病，腹满肠鸣，食不化，飧泄，甚则足痿不收，脉迟而涩，此寒邪乘脾也，$f{理中汤}主之；其着也，则髀枢强痛，不能屈伸，$f{枳实白术茯苓甘草汤}主之。', '2024-12-09T08:06:58.000Z', 1, NULL, '5IGM9t76quT', 'section', 'M43hMFfNOo1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2HsUOnzgt7P', 4, '{"title":"5","description":"<p>5、寒病，喘，咳，少气，不能报息，口唾涎沫，耳聋，嗌干，此寒邪乘肺也，脉沉而迟者，$f{甘草干姜汤}主之；其着也，则肘内痛，转侧不便，$f{枳实橘皮桔梗半夏生姜甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001405,"note":"","videoMemo":"","fangList":["枳实橘皮桔梗半夏生姜甘草汤","甘草干姜汤"],"bieMing":""}}', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '2024-12-09T08:06:58.000Z', '5、寒病，喘，咳，少气，不能报息，口唾涎沫，耳聋，嗌干，此寒邪乘肺也，脉沉而迟者，$f{甘草干姜汤}主之；其着也，则肘内痛，转侧不便，$f{枳实橘皮桔梗半夏生姜甘草汤}主之。', '2024-12-09T08:06:58.000Z', 1, NULL, '5IGM9t76quT', 'section', 'M43hMFfNOo1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p2zKsH44gpL', 4, '{"title":"1、太阳之为病，脉浮，头项强痛而恶寒","description":"<p>1、太阳之为病，脉浮，头项强痛而恶寒。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '1、太阳之为病，脉浮，头项强痛而恶寒。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7uqOgsVB84w', 4, '{"title":"2、太阳病，发热，汗出，恶风，脉缓者，名为中风","description":"<p>2、太阳病，发热，汗出，恶风，脉缓者，名为中风。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2、太阳病，发热，汗出，恶风，脉缓者，名为中风。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vEis8XIVshb', 4, '{"title":"3","description":"<p>3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名曰伤寒。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名曰伤寒。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wA2Y3er4N4V', 4, '{"title":"4","description":"<p>4、伤寒一日，太阳受之，脉若静者为不传；颇欲吐，若躁烦，脉数急者，此为传也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '4、伤寒一日，太阳受之，脉若静者为不传；颇欲吐，若躁烦，脉数急者，此为传也。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('drL1bpieRCg', 4, '{"title":"5、伤寒二三日，阳明、少阳证不见者，此为不传也","description":"<p>5、伤寒二三日，阳明、少阳证不见者，此为不传也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001505,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '5、伤寒二三日，阳明、少阳证不见者，此为不传也。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JOBaNREcPmn', 4, '{"title":"6、太阳病，发热而渴，不恶寒者，为温病","description":"<p>6、太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名曰风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，鼻息必鼾，语言难出。若被下者，小便不利，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘛疭；若火熏之，一逆尚引日，再逆促命期。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001506,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '6、太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名曰风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，鼻息必鼾，语言难出。若被下者，小便不利，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘛疭；若火熏之，一逆尚引日，再逆促命期。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vrisUL3FFrT', 4, '{"title":"7、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也","description":"<p>7、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七，阴数六故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001507,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '7、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七，阴数六故也。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TkyVqD9axQK', 4, '{"title":"8、太阳病，头痛至七日以上自愈者，以行其经尽故也","description":"<p>8、太阳病，头痛至七日以上自愈者，以行其经尽故也。若欲作再经者，针足阳明，使经不传则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001508,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '8、太阳病，头痛至七日以上自愈者，以行其经尽故也。若欲作再经者，针足阳明，使经不传则愈。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KdpLze8ADT4', 4, '{"title":"9、太阳病欲解时，从巳至未上","description":"<p>9、太阳病欲解时，从巳至未上。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001509,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '2024-12-10T09:20:16.000Z', '9、太阳病欲解时，从巳至未上。', '2024-12-10T09:20:16.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
