INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TeTij31xQdB', 4, '{"title":"17","description":"<p>17、太阳病三日，已发汗，若吐，若下，若温针，仍不解者，此为坏病，桂枝不可与也。观其脉证，知犯何逆，随证治之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001517,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '17、太阳病三日，已发汗，若吐，若下，若温针，仍不解者，此为坏病，桂枝不可与也。观其脉证，知犯何逆，随证治之。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qm6bnCV3tFK', 4, '{"title":"18","description":"<p>18、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常须识此，勿令误也。若酒客病，亦不可与$f{桂枝汤}，得之必呕，以酒客不喜甘故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001518,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '18、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常须识此，勿令误也。若酒客病，亦不可与$f{桂枝汤}，得之必呕，以酒客不喜甘故也。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
