INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TLsdydxIdWL', 4, '{"title":"22","description":"<p>22、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001522,"note":"","videoMemo":"","fangList":["桂枝去芍药汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '22、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
