INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('esW6iI9Nx5R', 4, '{"title":"24","description":"<p>24、太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发，脉微缓者，为欲愈也。脉微而恶寒，此阴阳俱虚，不可更发汗、更吐下也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001524,"note":"","videoMemo":"","fangList":["桂枝麻黄各半汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '24、太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发，脉微缓者，为欲愈也。脉微而恶寒，此阴阳俱虚，不可更发汗、更吐下也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6rgwW2beKOm', 4, '{"title":"25","description":"<p>25、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风府、风池，却与$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001525,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '25、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风府、风池，却与$f{桂枝汤}。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VgGehttkrPZ', 4, '{"title":"26","description":"<p>26、太阳病，服$f{桂枝汤}后，大汗出，脉洪大者，与$f{白虎汤}；若形如疟，一日再发者，宜$f{桂枝二麻黄一汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001526,"note":"","videoMemo":"","fangList":["桂枝汤","白虎汤","桂枝二麻黄一汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '26、太阳病，服$f{桂枝汤}后，大汗出，脉洪大者，与$f{白虎汤}；若形如疟，一日再发者，宜$f{桂枝二麻黄一汤}。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zvhKU6Nv3PZ', 4, '{"title":"27","description":"<p>27、太阳病，服$f{桂枝汤}后，大汗出，大烦渴，脉洪大者，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001527,"note":"","videoMemo":"","fangList":["桂枝汤","白虎加人参汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '27、太阳病，服$f{桂枝汤}后，大汗出，大烦渴，脉洪大者，$f{白虎加人参汤}主之。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gI2QXNncvt6', 4, '{"title":"28","description":"<p>28、太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，脉浮大者，宜$f{桂枝二越婢一汤}方。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001528,"note":"","videoMemo":"","fangList":["桂枝二越婢一汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '28、太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，脉浮大者，宜$f{桂枝二越婢一汤}方。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tKIgA6V26gv', 4, '{"title":"29","description":"<p>29、太阳病，服$f{桂枝汤}，或下之，仍头项强痛，翕翕发热，无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001529,"note":"","videoMemo":"","fangList":["桂枝汤","桂枝去桂加茯苓白术汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '29、太阳病，服$f{桂枝汤}，或下之，仍头项强痛，翕翕发热，无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HB4p9WYPtK4', 4, '{"title":"30","description":"<p>30、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与$f{桂枝汤}欲攻其表，此误也。得之便厥，咽中干，烦燥，吐逆者，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚即伸。若胃气不和，谵语者，少与$f{调胃承气汤}。若重发汗，复加烧针者，$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001530,"note":"","videoMemo":"","fangList":["桂枝汤","甘草干姜汤","芍药甘草汤","调胃承气汤","四逆汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '30、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与$f{桂枝汤}欲攻其表，此误也。得之便厥，咽中干，烦燥，吐逆者，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚即伸。若胃气不和，谵语者，少与$f{调胃承气汤}。若重发汗，复加烧针者，$f{四逆汤}主之。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JnQIu55QHyb', 4, '{"title":"31","description":"<p>31、问曰：太阳病，其证备，按桂枝法治之而增剧，厥逆，咽中干，烦躁，吐逆，谵语，其故何也？</p>\n<p>  </p>\n<p>       师曰：此阳旦证，不可攻也，寸口脉浮，浮则风，亦为虚，风则生热，虚则挛急。误攻其表煮取三升，去滓，温服一升，日三服汗出亡阳，汗多则液枯，液枯则筋挛，阳明内结则烦躁谵语，用甘草干姜以复其阳，芍药甘草以救液，调胃承气以止其谵语，此坏病之治必随脉证也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001531,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '31、问曰：太阳病，其证备，按桂枝法治之而增剧，厥逆，咽中干，烦躁，吐逆，谵语，其故何也？ 师曰：此阳旦证，不可攻也，寸口脉浮，浮则风，亦为虚，风则生热，虚则挛急。误攻其表煮取三升，去滓，温服一升，日三服汗出亡阳，汗多则液枯，液枯则筋挛，阳明内结则烦躁谵语，用甘草干姜以复其阳，芍药甘草以救液，调胃承气以止其谵语，此坏病之治必随脉证也。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6UIvknMlSFG', 4, '{"title":"32","description":"<p>32、阳旦证，发热不潮，汗出，咽干，昏睡不安，夜半反静者，宜$f{地黄半夏牡蛎酸枣仁汤}主之；若口渴，烦躁，小便赤，谵语者，$f{竹叶石膏黄芩泽泻半夏甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001532,"note":"","videoMemo":"","fangList":["地黄半夏牡蛎酸枣仁汤","竹叶石膏黄芩泽泻半夏甘草汤"],"bieMing":""}}', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '2024-12-10T09:33:38.000Z', '32、阳旦证，发热不潮，汗出，咽干，昏睡不安，夜半反静者，宜$f{地黄半夏牡蛎酸枣仁汤}主之；若口渴，烦躁，小便赤，谵语者，$f{竹叶石膏黄芩泽泻半夏甘草汤}主之。', '2024-12-10T09:33:38.000Z', 1, NULL, '5IGM9t76quT', 'section', 'rx41G0NS51e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kxTn66T0QPX', 4, '{"title":"33、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之","description":"<p>33、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016001,"note":"","videoMemo":"","fangList":["葛根汤"],"bieMing":""}}', '2024-12-11T04:01:59.000Z', '2024-12-11T04:01:59.000Z', '2024-12-11T04:01:59.000Z', '33、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。', '2024-12-11T04:01:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S4xynPLUOu6', 4, '{"title":"34、太阳与阳明合病者，必自下利，$f{葛根汤}主之","description":"<p>34、太阳与阳明合病者，必自下利，$f{葛根汤}主之。若不下利，但呕者，$f{葛根加半夏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016002,"note":"","videoMemo":"","fangList":["葛根加半夏汤","葛根汤"],"bieMing":""}}', '2024-12-11T04:01:59.000Z', '2024-12-11T04:01:59.000Z', '2024-12-11T04:01:59.000Z', '34、太阳与阳明合病者，必自下利，$f{葛根汤}主之。若不下利，但呕者，$f{葛根加半夏汤}主之。', '2024-12-11T04:01:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mp9Zb3nirF6', 4, '{"title":"3","description":"<p>35、太阳病，$n{桂枝}证，医反下之，利遂不止，脉促者，热未解也。喘而汗出者，$f{葛根黄连黄芩甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016003,"note":"","videoMemo":"","fangList":["葛根黄连黄芩甘草汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '35、太阳病，$n{桂枝}证，医反下之，利遂不止，脉促者，热未解也。喘而汗出者，$f{葛根黄连黄芩甘草汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VeO1B0Arozr', 4, '{"title":"4","description":"<p>36、太阳病，头痛发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016004,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '36、太阳病，头痛发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Va5yMCKP7kz', 4, '{"title":"37、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}","description":"<p>37、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016005,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '37、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QrV6yFYfDhn', 4, '{"title":"6","description":"<p>38、太阳病，十日已去，脉浮细而嗜卧者，外已解也，设胸满，胁痛，与$f{小柴胡汤}；脉但浮者，与$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016006,"note":"","videoMemo":"","fangList":["小柴胡汤","麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '38、太阳病，十日已去，脉浮细而嗜卧者，外已解也，设胸满，胁痛，与$f{小柴胡汤}；脉但浮者，与$f{麻黄汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kCScNFvoX8K', 4, '{"title":"7","description":"<p>39、太阳伤寒，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。若脉微弱，汗出恶风者，不可服之。服之则厥逆，筋惕肉（目闰），此为逆也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016007,"note":"","videoMemo":"","fangList":["大青龙汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '39、太阳伤寒，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。若脉微弱，汗出恶风者，不可服之。服之则厥逆，筋惕肉（目闰），此为逆也。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wo4sO6fQVI1', 4, '{"title":"8","description":"<p>40、太阳中风，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}发之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016008,"note":"","videoMemo":"","fangList":["大青龙汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '40、太阳中风，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}发之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F2G1CnuIfDK', 4, '{"title":"9","description":"<p>41、伤寒表不解，心下有水气，干呕发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016009,"note":"","videoMemo":"","fangList":["小青龙汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '41、伤寒表不解，心下有水气，干呕发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nASntWpQI5E', 4, '{"title":"42、伤寒，心下有水气，咳而微喘，发热不渴","description":"<p>42、伤寒，心下有水气，咳而微喘，发热不渴。服汤已渴者，此寒去欲解也。$f{小青龙汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016010,"note":"","videoMemo":"","fangList":["小青龙汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '42、伤寒，心下有水气，咳而微喘，发热不渴。服汤已渴者，此寒去欲解也。$f{小青龙汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SwUdOhUwiIM', 4, '{"title":"11","description":"<p>43、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016011,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '43、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ob9eFjfu9wT', 4, '{"title":"44、太阳病，下之微喘者，表未解故也","description":"<p>44、太阳病，下之微喘者，表未解故也。$f{桂枝加厚朴杏子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016012,"note":"","videoMemo":"","fangList":["桂枝加厚朴杏子汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '44、太阳病，下之微喘者，表未解故也。$f{桂枝加厚朴杏子汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dfdFeRpHKE6', 4, '{"title":"45、太阳病，外证未解，不可下也，下之为逆","description":"<p>45、太阳病，外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016013,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '45、太阳病，外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FfAJeccvK76', 4, '{"title":"46、太阳病，先发汗不解，而复下之，脉浮者不愈","description":"<p>46、太阳病，先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，当须解外则愈，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016014,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '46、太阳病，先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，当须解外则愈，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BVN1JucqTrq', 4, '{"title":"15","description":"<p>47、太阳病，脉浮紧，无汗，发热，身疼痛，八九日不解，表证仍在，此当发其汗。服药已，微除，其人发烦目瞑。剧者必衄，衄乃解，所以然者，阳气重故也。$f{麻黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016015,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '47、太阳病，脉浮紧，无汗，发热，身疼痛，八九日不解，表证仍在，此当发其汗。服药已，微除，其人发烦目瞑。剧者必衄，衄乃解，所以然者，阳气重故也。$f{麻黄汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hofhmSqjp1k', 4, '{"title":"48、太阳病，脉浮紧，发热，身无汗，自衄者愈","description":"<p>48、太阳病，脉浮紧，发热，身无汗，自衄者愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '48、太阳病，脉浮紧，发热，身无汗，自衄者愈。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AcmhH57oqT0', 4, '{"title":"17","description":"<p>49、二阳并病，太阳初得病时，发其汗，汗先出不彻，因转属阳明，续自微汗出，不恶寒。若太阳病证不罢者，不可下，下之为逆，如此可小发其汗。设面色缘缘正赤者，阳气怫郁在表也，当解之、熏之；若发汗不彻，彻不足言，阳气怫郁不得越，当汗之不汗，则其人烦燥，不知痛处，乍在腹中，乍在四肢，按之不可得，更发汗则愈；若其人短气，但坐者，以汗出不彻故也，何以知汗出不彻？以脉涩故知之也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '49、二阳并病，太阳初得病时，发其汗，汗先出不彻，因转属阳明，续自微汗出，不恶寒。若太阳病证不罢者，不可下，下之为逆，如此可小发其汗。设面色缘缘正赤者，阳气怫郁在表也，当解之、熏之；若发汗不彻，彻不足言，阳气怫郁不得越，当汗之不汗，则其人烦燥，不知痛处，乍在腹中，乍在四肢，按之不可得，更发汗则愈；若其人短气，但坐者，以汗出不彻故也，何以知汗出不彻？以脉涩故知之也。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YlnGnHhOA0d', 4, '{"title":"50、脉浮紧者，法当汗出而解","description":"<p>50、脉浮紧者，法当汗出而解。若身重心悸者，不可发汗，须自汗出乃愈。所以然者，尺中脉微，此里虚也，须里实津液自和，便自汗出愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '50、脉浮紧者，法当汗出而解。若身重心悸者，不可发汗，须自汗出乃愈。所以然者，尺中脉微，此里虚也，须里实津液自和，便自汗出愈。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TRp87tU04WJ', 4, '{"title":"51、脉浮紧者，法当身疼痛，宜以汗解之","description":"<p>51、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以然者，以荣气不足，血弱故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '51、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以然者，以荣气不足，血弱故也。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lj9qo6c48zX', 4, '{"title":"52、脉浮者，病在表，可发汗，宜$f{麻黄汤}","description":"<p>52、脉浮者，病在表，可发汗，宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016020,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '52、脉浮者，病在表，可发汗，宜$f{麻黄汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gC2d0OK93mp', 4, '{"title":"53、脉浮而紧者，可发汗，宜$f{麻黄汤}","description":"<p>53、脉浮而紧者，可发汗，宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016021,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '53、脉浮而紧者，可发汗，宜$f{麻黄汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Pa8DpYSaHS', 4, '{"title":"22","description":"<p>54、病人常自汗出者，此为荣气和，卫气不谐也，所以然者，荣行脉中，卫行脉外，卫气不共荣气和谐故也。复发其汗则愈，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016022,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '54、病人常自汗出者，此为荣气和，卫气不谐也，所以然者，荣行脉中，卫行脉外，卫气不共荣气和谐故也。复发其汗则愈，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aZeLTFbij3m', 4, '{"title":"55、病人脏无他病，时发热自汗出而不愈者，此卫气不和也","description":"<p>55、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016023,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '55、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H6LuahnqxdP', 4, '{"title":"56、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之","description":"<p>56、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016024,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '56、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O7r1XTFFY6N', 4, '{"title":"57、伤寒，不大便六七日，头痛有热者，与$n{承气汤}","description":"<p>57、伤寒，不大便六七日，头痛有热者，与$n{承气汤}。其小便清者，知不在里，仍在表也，当须发汗，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016025,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '57、伤寒，不大便六七日，头痛有热者，与$n{承气汤}。其小便清者，知不在里，仍在表也，当须发汗，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bvn7kgv8YM9', 4, '{"title":"26","description":"<p>58、伤寒，发汗已解，半日许复烦，脉浮紧者，可更发汗，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016026,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '58、伤寒，发汗已解，半日许复烦，脉浮紧者，可更发汗，宜$f{桂枝汤}。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vr0cLqZBo4X', 4, '{"title":"27","description":"<p>59、凡病若发汗、若吐、若下、若亡血、亡津液，阴阳自和者，必自愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '59、凡病若发汗、若吐、若下、若亡血、亡津液，阴阳自和者，必自愈。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QWHRq6nCX5f', 4, '{"title":"28","description":"<p>60、大下之后，复下之，小便不利者，亡津液故也，勿治之，久久小便必自利。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '60、大下之后，复下之，小便不利者，亡津液故也，勿治之，久久小便必自利。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8aOmVAk7BUi', 4, '{"title":"61、大下之后，复发汗，其人必振寒，脉微细","description":"<p>61、大下之后，复发汗，其人必振寒，脉微细。所以然者，内外俱虚故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '61、大下之后，复发汗，其人必振寒，脉微细。所以然者，内外俱虚故也。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cVN1UJ6kJi2', 4, '{"title":"30","description":"<p>62、下之后，复发汗，昼日烦躁，不得眠，夜而安静，不呕不渴，无表证，脉沉而微，身无大热者，$f{干姜附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016030,"note":"","videoMemo":"","fangList":["干姜附子汤"],"bieMing":""}}', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '2024-12-11T06:16:33.000Z', '62、下之后，复发汗，昼日烦躁，不得眠，夜而安静，不呕不渴，无表证，脉沉而微，身无大热者，$f{干姜附子汤}主之。', '2024-12-11T06:16:33.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
