INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LZ0GwSC6UZQ', 4, '{"title":"34","description":"<p>66、发汗后，其人脐下悸者，欲作奔豚也，$f{茯苓桂枝甘草大枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016034,"note":"","videoMemo":"","fangList":["茯苓桂枝甘草大枣汤"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '66、发汗后，其人脐下悸者，欲作奔豚也，$f{茯苓桂枝甘草大枣汤}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
