INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0iJzqBVNsnF', 4, '{"title":"38","description":"<p>70、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016038,"note":"","videoMemo":"","fangList":["茯苓桂枝白术甘草汤"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '70、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
