INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o9XU1ZhFg9k', 4, '{"title":"72、发汗若下之，病仍不解，烦躁者，$f{茯苓四逆汤}主之","description":"<p>72、发汗若下之，病仍不解，烦躁者，$f{茯苓四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016040,"note":"","videoMemo":"","fangList":["茯苓四逆汤"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '72、发汗若下之，病仍不解，烦躁者，$f{茯苓四逆汤}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZSPqUyXWEZr', 4, '{"title":"73、发汗后，恶寒者，虚故也；不恶寒，但热者，实也","description":"<p>73、发汗后，恶寒者，虚故也；不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016041,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '73、发汗后，恶寒者，虚故也；不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UL9xYAeogXW', 4, '{"title":"42","description":"<p>74、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水，少少与之，令胃气和则愈。若脉浮，小便不利，微热消渴者，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016042,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '74、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水，少少与之，令胃气和则愈。若脉浮，小便不利，微热消渴者，$f{五苓散}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NpP5r1IO4mO', 4, '{"title":"75、太阳病，发汗已，脉浮弦，烦渴者，$f{五苓散}主之","description":"<p>75、太阳病，发汗已，脉浮弦，烦渴者，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016043,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '75、太阳病，发汗已，脉浮弦，烦渴者，$f{五苓散}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T775g9sal7e', 4, '{"title":"76、伤寒汗出而渴，小便不利者，${五苓散}主之","description":"<p>76、伤寒汗出而渴，小便不利者，${五苓散}主之。不渴者，$f{茯苓甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016044,"note":"","videoMemo":"","fangList":["五苓散","茯苓甘草汤"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '76、伤寒汗出而渴，小便不利者，${五苓散}主之。不渴者，$f{茯苓甘草汤}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q5ZLJaC1Xrc', 4, '{"title":"45","description":"<p>77、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆。$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016045,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '77、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆。$f{五苓散}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EhHWAbZEVTR', 4, '{"title":"46","description":"<p>78、未持脉时，病人叉手自冒心，师因试教令咳而不咳者，此必两耳聋无所闻也。所以然者，以重发汗，虚故此。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016046,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '78、未持脉时，病人叉手自冒心，师因试教令咳而不咳者，此必两耳聋无所闻也。所以然者，以重发汗，虚故此。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q87n46vJ68X', 4, '{"title":"79、发汗后，饮水多，必喘，以水灌之，亦喘","description":"<p>79、发汗后，饮水多，必喘，以水灌之，亦喘。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016047,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '79、发汗后，饮水多，必喘，以水灌之，亦喘。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
