INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tOqFZ370bAO', 4, '{"title":"49","description":"<p>81、发汗后及吐下后，虚烦不得眠；若剧者，必反覆颠倒，心中懊憹，$f{栀子干姜汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016049,"note":"","videoMemo":"","fangList":["栀子干姜汤","栀子甘草豉汤","栀子生姜豉汤"],"bieMing":""}}', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '2024-12-11T07:19:14.000Z', '81、发汗后及吐下后，虚烦不得眠；若剧者，必反覆颠倒，心中懊憹，$f{栀子干姜汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。', '2024-12-11T07:19:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
