INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UO4mHMmbHVQ', 4, '{"title":"95、伤寒，未发汗，而复下之，此为逆也；若先发汗，治不为逆","description":"<p>95、伤寒，未发汗，而复下之，此为逆也；若先发汗，治不为逆。本先下之，而反汗之为逆；若先下之，治不为逆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016063,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '95、伤寒，未发汗，而复下之，此为逆也；若先发汗，治不为逆。本先下之，而反汗之为逆；若先下之，治不为逆。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KTSexsfvukK', 4, '{"title":"64","description":"<p>96、伤寒医下之，续得下利清谷不止，身疼痛者，急当救里；后身疼痛，清便自调者，急当救表。救里宜$f{四逆汤}；救表宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016064,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '96、伤寒医下之，续得下利清谷不止，身疼痛者，急当救里；后身疼痛，清便自调者，急当救表。救里宜$f{四逆汤}；救表宜$f{桂枝汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HuX43HY7qFv', 4, '{"title":"65","description":"<p>97、太阳病，先下而不愈，因复发汗，以此表里俱虚，其人因致冒，冒家汗自出愈，所以然者，表和故也，里未和然后复下之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016065,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '97、太阳病，先下而不愈，因复发汗，以此表里俱虚，其人因致冒，冒家汗自出愈，所以然者，表和故也，里未和然后复下之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WIrMSohU4sV', 4, '{"title":"98、太阳病未解，脉阴阳俱微者，必先振栗汗出而解","description":"<p>98、太阳病未解，脉阴阳俱微者，必先振栗汗出而解。但阳脉微者，先汗出而解；若阴脉实者，下之而解。若欲下之，宜$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016066,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '98、太阳病未解，脉阴阳俱微者，必先振栗汗出而解。但阳脉微者，先汗出而解；若阴脉实者，下之而解。若欲下之，宜$f{调胃承气汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NjuW0aLmHAW', 4, '{"title":"67","description":"<p>99、太阳病，发热汗出者，此为荣弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016067,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '99、太阳病，发热汗出者，此为荣弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6u6glTbZk8X', 4, '{"title":"68","description":"<p>100、伤寒五六日，中风，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身有微热，或咳者，与$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016068,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '100、伤寒五六日，中风，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身有微热，或咳者，与$f{小柴胡汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('38F3MLZr8pN', 4, '{"title":"69","description":"<p>101、血弱气尽，腠理开，邪气因入，与正气相搏，结于胁下，正邪纷争，往来寒热，休作有时，嘿嘿不欲饮食。脏腑相连，其痛必下，邪高痛下，故使呕也。$f{小柴胡汤}主之。服柴胡汤已，渴者，属阳明也，以法治之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016069,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '101、血弱气尽，腠理开，邪气因入，与正气相搏，结于胁下，正邪纷争，往来寒热，休作有时，嘿嘿不欲饮食。脏腑相连，其痛必下，邪高痛下，故使呕也。$f{小柴胡汤}主之。服柴胡汤已，渴者，属阳明也，以法治之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iZyUG1I1R7J', 4, '{"title":"70","description":"<p>102、太阳病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤。后必下重，本渴而饮水呕者，柴胡不中与也。食谷者哕。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016070,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '102、太阳病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤。后必下重，本渴而饮水呕者，柴胡不中与也。食谷者哕。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xCPTJtY1b8q', 4, '{"title":"71","description":"<p>103、伤寒四五日，身热恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016071,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '103、伤寒四五日，身热恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UCmqQjpUsyE', 4, '{"title":"72","description":"<p>104、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}；不差者，与$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016072,"note":"","videoMemo":"","fangList":["小建中汤","小柴胡汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '104、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}；不差者，与$f{小柴胡汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QKOVp5PA5CQ', 4, '{"title":"105、伤寒与中风，有柴胡证，但见一证便是，不必悉具","description":"<p>105、伤寒与中风，有柴胡证，但见一证便是，不必悉具。凡柴胡汤病证而误下之，若柴胡证不罢者，复与柴胡汤，必蒸蒸而振，却复发热汗出而解。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016073,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '105、伤寒与中风，有柴胡证，但见一证便是，不必悉具。凡柴胡汤病证而误下之，若柴胡证不罢者，复与柴胡汤，必蒸蒸而振，却复发热汗出而解。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Insq0B6WMZj', 4, '{"title":"106、伤寒二三日，心中悸而烦者，$f{小建中汤}主之","description":"<p>106、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016074,"note":"","videoMemo":"","fangList":["小建中汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '106、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W0D4cN0yyrb', 4, '{"title":"75","description":"<p>107、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016075,"note":"","videoMemo":"","fangList":["小柴胡汤","大柴胡汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '107、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fqPCrXcNA8s', 4, '{"title":"108、伤寒十三日不解，胸胁满而呕，日晡所发潮热，已而微利","description":"<p>108、伤寒十三日不解，胸胁满而呕，日晡所发潮热，已而微利。此本柴胡证，下之以不得利，今反利者，知医以丸药下之，非其治也。潮热者实也，宜先服$f{小柴胡汤}以解外，后以$f{柴胡加芒消汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016076,"note":"","videoMemo":"","fangList":["小柴胡汤","柴胡加芒消汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '108、伤寒十三日不解，胸胁满而呕，日晡所发潮热，已而微利。此本柴胡证，下之以不得利，今反利者，知医以丸药下之，非其治也。潮热者实也，宜先服$f{小柴胡汤}以解外，后以$f{柴胡加芒消汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IgDzcRLalaZ', 4, '{"title":"109、伤寒十三日，过经，谵语者，以有热也，当以汤下之","description":"<p>109、伤寒十三日，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，知医以丸药下之，非其治也。若自下利者，脉当微厥，今反和者，此为内实也，$f{调胃承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016077,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '109、伤寒十三日，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，知医以丸药下之，非其治也。若自下利者，脉当微厥，今反和者，此为内实也，$f{调胃承气汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IDDz8A3apHW', 4, '{"title":"110、太阳病不解，热结膀胱，其人如狂，血自下，下者愈","description":"<p>110、太阳病不解，热结膀胱，其人如狂，血自下，下者愈。其外不解者，尚未可攻，当先解外。外解已，但少腹急结者，乃可攻之，宜$f{桃仁承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016078,"note":"","videoMemo":"","fangList":["桃仁承气汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '110、太阳病不解，热结膀胱，其人如狂，血自下，下者愈。其外不解者，尚未可攻，当先解外。外解已，但少腹急结者，乃可攻之，宜$f{桃仁承气汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1D97dYjx2vz', 4, '{"title":"79","description":"<p>111、伤寒八九日，下之，胸满烦惊，小便不利，谵语，一身尽重，不可转侧，$f{柴胡加龙骨牡蛎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016079,"note":"","videoMemo":"","fangList":["柴胡加龙骨牡蛎汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '111、伤寒八九日，下之，胸满烦惊，小便不利，谵语，一身尽重，不可转侧，$f{柴胡加龙骨牡蛎汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MZkNpbfB0Da', 4, '{"title":"80","description":"<p>112、伤寒，腹满，谵语，寸口脉浮而紧，关上弦者，此肝乘脾也，名曰纵，刺期门。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016080,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '112、伤寒，腹满，谵语，寸口脉浮而紧，关上弦者，此肝乘脾也，名曰纵，刺期门。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KzAPSP25xiX', 4, '{"title":"81","description":"<p>113、伤寒发热，啬啬恶寒，大渴欲饮水，其腹必满，自汗出，小便不寸口脉浮而涩，关上弦急者，此肝乘肺也，名曰横，刺期门。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016081,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '113、伤寒发热，啬啬恶寒，大渴欲饮水，其腹必满，自汗出，小便不寸口脉浮而涩，关上弦急者，此肝乘肺也，名曰横，刺期门。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UiygZ7zGzvK', 4, '{"title":"82","description":"<p>114、太阳病二日，烦躁，反熨其背，而大汗出，火热入胃，胃中水竭，躁烦，必发谵语，十余日，振栗、自下利者，此为欲解也。若其汗从腰以下不得汗，欲小便不得，反呕，欲失溲，足下恶风，大便鞕，小便当数，而反不数又不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016082,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '114、太阳病二日，烦躁，反熨其背，而大汗出，火热入胃，胃中水竭，躁烦，必发谵语，十余日，振栗、自下利者，此为欲解也。若其汗从腰以下不得汗，欲小便不得，反呕，欲失溲，足下恶风，大便鞕，小便当数，而反不数又不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CrPr8cRWgrf', 4, '{"title":"83","description":"<p>115、太阳病中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥。但头汗出，剂颈而还，腹满微喘，口干咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床，小便利者，其人可治。宜$f{人参地黄龙骨牡蛎茯苓汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016083,"note":"","videoMemo":"","fangList":["人参地黄龙骨牡蛎茯苓汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '115、太阳病中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥。但头汗出，剂颈而还，腹满微喘，口干咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床，小便利者，其人可治。宜$f{人参地黄龙骨牡蛎茯苓汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ifkQT2gMKhc', 4, '{"title":"84","description":"<p>116、伤寒脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加牡蛎龙骨救逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016084,"note":"","videoMemo":"","fangList":["桂枝去芍药加牡蛎龙骨救逆汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '116、伤寒脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加牡蛎龙骨救逆汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0qPMJ3jMqrN', 4, '{"title":"117、形似伤寒，其脉不弦紧而弱","description":"<p>117、形似伤寒，其脉不弦紧而弱。弱者必渴，被火必谵语。弱而发热、脉浮者，解之当汗出愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016085,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '117、形似伤寒，其脉不弦紧而弱。弱者必渴，被火必谵语。弱而发热、脉浮者，解之当汗出愈。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3nlF6f7Ty8E', 4, '{"title":"86","description":"<p>118、太阳病，以火熏之，不得汗，其人必躁，到经不解，必清血，名为火邪。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016086,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '118、太阳病，以火熏之，不得汗，其人必躁，到经不解，必清血，名为火邪。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4Vb65ieI92f', 4, '{"title":"119、脉浮热甚，反以火灸之，此为实","description":"<p>119、脉浮热甚，反以火灸之，此为实。实以虚治，因火而动，必咽燥唾血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016087,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '119、脉浮热甚，反以火灸之，此为实。实以虚治，因火而动，必咽燥唾血。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t3OIP797zCW', 4, '{"title":"88","description":"<p>120、微数之脉，慎不可灸，因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016088,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '120、微数之脉，慎不可灸，因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X5ETieEMCi8', 4, '{"title":"89","description":"<p>121、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也。欲自解者，必当先烦，乃有汗而解。何以知之？脉浮故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016089,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '121、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也。欲自解者，必当先烦，乃有汗而解。何以知之？脉浮故也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TTrSP2FZBqx', 4, '{"title":"122、烧针令其汗，针处被寒，核起而赤者，必发奔豚","description":"<p>122、烧针令其汗，针处被寒，核起而赤者，必发奔豚。气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016090,"note":"","videoMemo":"","fangList":["桂枝加桂汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '122、烧针令其汗，针处被寒，核起而赤者，必发奔豚。气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R8s5HEtyO1t', 4, '{"title":"91","description":"<p>123、火逆，下之，因烧针烦躁者，$f{桂枝甘草龙骨牡蛎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016091,"note":"","videoMemo":"","fangList":["桂枝甘草龙骨牡蛎汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '123、火逆，下之，因烧针烦躁者，$f{桂枝甘草龙骨牡蛎汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xnMRu3QyfTQ', 4, '{"title":"124、太阳伤寒者，加温针，必惊也","description":"<p>124、太阳伤寒者，加温针，必惊也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016092,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '124、太阳伤寒者，加温针，必惊也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QaSRV9mtm4n', 4, '{"title":"93","description":"<p>125、太阳病，当恶寒发热，今自汗出，反不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，此为小逆；若不恶寒，又不欲近衣者，此为内烦；皆医吐之所致也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016093,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '125、太阳病，当恶寒发热，今自汗出，反不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，此为小逆；若不恶寒，又不欲近衣者，此为内烦；皆医吐之所致也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JTLYUMXvqMf', 4, '{"title":"94","description":"<p>126、病人脉数，数为热，当消谷，今引食而反吐者，此以发汗令阳气微，隔气虚，脉乃数也。数为客热，故不能消谷，以胃中虚冷故吐也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016094,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '126、病人脉数，数为热，当消谷，今引食而反吐者，此以发汗令阳气微，隔气虚，脉乃数也。数为客热，故不能消谷，以胃中虚冷故吐也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H5lSI1UtX11', 4, '{"title":"95","description":"<p>127、太阳病，过经十余日，心中温温欲吐，胸中痛，大便反溏，腹微满，郁郁微烦。先其时，自极吐下者，与$f{调胃承气汤}。若不尔者，不可与之。若但欲呕，胸中痛，微溏者，此非柴胡证，所以然者，以呕故知极吐下也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016095,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '127、太阳病，过经十余日，心中温温欲吐，胸中痛，大便反溏，腹微满，郁郁微烦。先其时，自极吐下者，与$f{调胃承气汤}。若不尔者，不可与之。若但欲呕，胸中痛，微溏者，此非柴胡证，所以然者，以呕故知极吐下也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9lX8n1P0obk', 4, '{"title":"96","description":"<p>128、太阳病六七日，表证仍在，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈，所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016096,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '128、太阳病六七日，表证仍在，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈，所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sI3SbV2OgV6', 4, '{"title":"97","description":"<p>129、太阳病，身黄脉沉结，少腹鞕，小便不利者，为无血也；小便自利，其人如狂者，血证谛也，$f{抵当汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016097,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '129、太阳病，身黄脉沉结，少腹鞕，小便不利者，为无血也；小便自利，其人如狂者，血证谛也，$f{抵当汤}主之。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('waUXUWjptAZ', 4, '{"title":"98","description":"<p>130、伤寒有热，少腹满，应小便不利；今反利者，为有血也，当下之，可不余药，宜$f{抵当丸}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016098,"note":"","videoMemo":"","fangList":["抵当丸"],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '130、伤寒有热，少腹满，应小便不利；今反利者，为有血也，当下之，可不余药，宜$f{抵当丸}。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MJOl38NkNUG', 4, '{"title":"131、太阳病，小便利者，以饮水多，必心下悸","description":"<p>131、太阳病，小便利者，以饮水多，必心下悸。小便少者，必苦里急也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001016099,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '2024-12-11T08:05:20.000Z', '131、太阳病，小便利者，以饮水多，必心下悸。小便少者，必苦里急也。', '2024-12-11T08:05:20.000Z', 1, NULL, '5IGM9t76quT', 'section', 'VtBGNLOZPUA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6rwWcDI56IM', 4, '{"title":"1","description":"<p>132、问曰：病有脏结，有结胸，其状何如？</p>\n<p></p>\n<p>         师曰：寸脉浮，关脉小细沉紧者，名曰脏结也。按之痛，寸脉浮，关脉沉，名曰结胸也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T02:21:37.000Z', '2024-12-14T02:21:37.000Z', '2024-12-14T02:21:37.000Z', '132、问曰：病有脏结，有结胸，其状何如？ 师曰：寸脉浮，关脉小细沉紧者，名曰脏结也。按之痛，寸脉浮，关脉沉，名曰结胸也。', '2024-12-14T02:21:37.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AdvwJtGbjlb', 4, '{"title":"133、何谓脏结","description":"<p>133、何谓脏结？</p>\n<p></p>\n<p>       师曰：脏结者，五脏各具，寒热攸分，宜求血分，虽有气结，皆血为之。假令肝脏结，则两胁痛而呕，脉沉弦而结者，宜$f{吴茱萸汤}。若发热不呕者，此为实，脉当沉弦而急，$f{桂枝当归牡丹皮桃仁枳实汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001702,"note":"","videoMemo":"","fangList":["吴茱萸汤","桂枝当归牡丹皮桃仁枳实汤"],"bieMing":""}}', '2024-12-14T02:21:37.000Z', '2024-12-14T02:21:37.000Z', '2024-12-14T02:21:37.000Z', '133、何谓脏结？ 师曰：脏结者，五脏各具，寒热攸分，宜求血分，虽有气结，皆血为之。假令肝脏结，则两胁痛而呕，脉沉弦而结者，宜$f{吴茱萸汤}。若发热不呕者，此为实，脉当沉弦而急，$f{桂枝当归牡丹皮桃仁枳实汤}主之。', '2024-12-14T02:21:37.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yKhOQ06hs3Z', 4, '{"title":"3","description":"<p>134、心脏结，则心中痛，或在心下郁郁不乐，脉大而涩，$f{连翘阿胶半夏赤小豆汤}主之。若心中热痛而烦，脉大而弦急者，此为实也，$f{黄连阿胶半夏桃仁茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001703,"note":"","videoMemo":"","fangList":["连翘阿胶半夏赤小豆汤","黄连阿胶半夏桃仁茯苓汤"],"bieMing":""}}', '2024-12-14T04:01:23.000Z', '2024-12-14T04:01:23.000Z', '2024-12-14T04:01:23.000Z', '134、心脏结，则心中痛，或在心下郁郁不乐，脉大而涩，$f{连翘阿胶半夏赤小豆汤}主之。若心中热痛而烦，脉大而弦急者，此为实也，$f{黄连阿胶半夏桃仁茯苓汤}主之。', '2024-12-14T04:01:23.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9irrnsmfE1c', 4, '{"title":"4","description":"<p>135、肺脏结，胸中闭塞，喘，咳，善悲，脉短而涩，$f{百合贝母茯苓桔梗汤}主之。若咳而唾血，胸中痛，此为实，$f{葶苈括蒌桔梗牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001704,"note":"","videoMemo":"","fangList":["百合贝母茯苓桔梗汤","葶苈括蒌桔梗牡丹汤"],"bieMing":""}}', '2024-12-14T04:01:23.000Z', '2024-12-14T04:01:23.000Z', '2024-12-14T04:01:23.000Z', '135、肺脏结，胸中闭塞，喘，咳，善悲，脉短而涩，$f{百合贝母茯苓桔梗汤}主之。若咳而唾血，胸中痛，此为实，$f{葶苈括蒌桔梗牡丹汤}主之。', '2024-12-14T04:01:23.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PMxjvjvdf1E', 4, '{"title":"5","description":"<p>136、脾脏结，腹中满痛，按之如覆杯，甚则腹大而坚，脉沉而紧，$f{白术枳实桃仁干姜汤}主之。若腹中胀痛，不可按，大便初溏后鞕，转失（疑为矢）气者，此为实，$f{大黄厚朴枳实半夏甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001705,"note":"","videoMemo":"","fangList":["白术枳实桃仁干姜汤","大黄厚朴枳实半夏甘草汤"],"bieMing":""}}', '2024-12-14T04:01:23.000Z', '2024-12-14T04:01:23.000Z', '2024-12-14T04:01:23.000Z', '136、脾脏结，腹中满痛，按之如覆杯，甚则腹大而坚，脉沉而紧，$f{白术枳实桃仁干姜汤}主之。若腹中胀痛，不可按，大便初溏后鞕，转失（疑为矢）气者，此为实，$f{大黄厚朴枳实半夏甘草汤}主之。', '2024-12-14T04:01:23.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zC6Oh083j3h', 4, '{"title":"6","description":"<p>137、肾脏结，少腹鞕，隐隐痛，按之如有核，小便乍清乍浊，脉沉细而结，宜$f{茯苓桂枝甘草大枣汤}。若小腹急痛，小便赤数者，此为实，宜$f{桂枝茯苓枳实芍药甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001706,"note":"","videoMemo":"","fangList":["茯苓桂枝甘草大枣汤","桂枝茯苓枳实芍药甘草汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '137、肾脏结，少腹鞕，隐隐痛，按之如有核，小便乍清乍浊，脉沉细而结，宜$f{茯苓桂枝甘草大枣汤}。若小腹急痛，小便赤数者，此为实，宜$f{桂枝茯苓枳实芍药甘草汤}。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sMaW375EfEQ', 4, '{"title":"7","description":"<p>138、脏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也；饮食如故，时时下利，舌上白苔滑者，为难治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '138、脏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也；饮食如故，时时下利，舌上白苔滑者，为难治。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ddQxTpW5Klz', 4, '{"title":"8","description":"<p>139、何谓结胸？师曰：病发于阳而反下之，热入于里，因作结胸。病发于阴，而早下之，因作痞。所以成结胸者，误下故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001708,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '139、何谓结胸？师曰：病发于阳而反下之，热入于里，因作结胸。病发于阴，而早下之，因作痞。所以成结胸者，误下故也。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('63apW4UUsdw', 4, '{"title":"9","description":"<p>140、结胸病，头项强，如柔痉状者，下之则和，宜$f{大陷胸丸}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001709,"note":"","videoMemo":"","fangList":["大陷胸丸"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '140、结胸病，头项强，如柔痉状者，下之则和，宜$f{大陷胸丸}。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qJ05QZdw42M', 4, '{"title":"141、结胸证，其脉浮大者，不可下，下之则死","description":"<p>141、结胸证，其脉浮大者，不可下，下之则死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '141、结胸证，其脉浮大者，不可下，下之则死。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yOvC4ofSJ36', 4, '{"title":"142、结胸证悉具，烦躁者，亦死","description":"<p>142、结胸证悉具，烦躁者，亦死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001711,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '142、结胸证悉具，烦躁者，亦死。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4ZgC1FY5KD5', 4, '{"title":"12","description":"<p>143、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气，躁烦，心中懊$n{憹[náo]}，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001712,"note":"","videoMemo":"","fangList":["大陷胸汤","五苓散"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '143、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气，躁烦，心中懊$n{憹[náo]}，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。$f{五苓散}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DT6HB8wEFJi', 4, '{"title":"13","description":"<p>144、伤寒六七日，结胸热实，脉沉紧而实，心下痛，按之石鞕者，$f{大陷胸汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001713,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '144、伤寒六七日，结胸热实，脉沉紧而实，心下痛，按之石鞕者，$f{大陷胸汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kxHVz03C34j', 4, '{"title":"14","description":"<p>145、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001714,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '145、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tpIDiLBPuRC', 4, '{"title":"15","description":"<p>146、但结胸无大热者，此为水结在胸肋也，但头微汗出者，$f{大陷胸汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001715,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '146、但结胸无大热者，此为水结在胸肋也，但头微汗出者，$f{大陷胸汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FAX2ID3aROg', 4, '{"title":"16","description":"<p>147、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日晡所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001716,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '147、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日晡所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e6QfIzs4hnF', 4, '{"title":"17","description":"<p>148、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001717,"note":"","videoMemo":"","fangList":["小陷胸汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '148、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MzH0wSRxQo9', 4, '{"title":"18","description":"<p>149、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，此本有寒分也，反下之，若利止，必作结胸；未止者，此作协热利也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001718,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '149、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，此本有寒分也，反下之，若利止，必作结胸；未止者，此作协热利也。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DabXhZsAzSZ', 4, '{"title":"19","description":"<p>150、太阳病，下之后，其脉促，不结胸者，此为欲解也；脉浮者，必结胸；脉紧者，必咽痛，脉弦者，必两胁拘急；脉细数者，头痛未止，脉沉紧者，必欲呕；脉沉滑者，协热利；脉浮滑者，必下血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001719,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '150、太阳病，下之后，其脉促，不结胸者，此为欲解也；脉浮者，必结胸；脉紧者，必咽痛，脉弦者，必两胁拘急；脉细数者，头痛未止，脉沉紧者，必欲呕；脉沉滑者，协热利；脉浮滑者，必下血。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ssvs3rdmEOs', 4, '{"title":"20","description":"<p>151、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，肉上粟起，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。寒实结胸，无热证者，与$n{三物}$f{小陷胸汤}，$f{白散}亦可服。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001720,"note":"","videoMemo":"","fangList":["文蛤散","五苓散","小陷胸汤","白散"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '151、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，肉上粟起，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。寒实结胸，无热证者，与$n{三物}$f{小陷胸汤}，$f{白散}亦可服。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ygCjKNp1njr', 4, '{"title":"21","description":"<p>152、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗，发汗则谵语，脉弦大，五日谵语不止，当刺期门。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001721,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '152、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗，发汗则谵语，脉弦大，五日谵语不止，当刺期门。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jcpaW9hbUdR', 4, '{"title":"22","description":"<p>153、妇人中风，发热恶风，经水适来，得之七八日，热除而脉迟身凉，胸胁下满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泄之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001722,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '153、妇人中风，发热恶风，经水适来，得之七八日，热除而脉迟身凉，胸胁下满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泄之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KbdX7IIe40e', 4, '{"title":"23","description":"<p>154、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001723,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '154、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，$f{小柴胡汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tA5aoo2wG61', 4, '{"title":"24","description":"<p>155、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上二焦，必自愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001724,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '155、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上二焦，必自愈。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J5LDL0Io3l3', 4, '{"title":"25","description":"<p>156、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001725,"note":"","videoMemo":"","fangList":["柴胡桂枝汤"],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '156、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('64OkeRKHeHn', 4, '{"title":"26","description":"<p>157、伤寒五六日，已发汗而复下之，胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001726,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '2024-12-14T06:51:21.000Z', '157、伤寒五六日，已发汗而复下之，胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。', '2024-12-14T06:51:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GDVowjuzSaI', 4, '{"title":"27","description":"<p>158、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉细者，此为阳微结，必有表复有里也，脉沉者，亦在里也，汗出为阳微。假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也，脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴也，可与$f{小柴胡汤}。设不了了者，得屎而解。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001727,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '158、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉细者，此为阳微结，必有表复有里也，脉沉者，亦在里也，汗出为阳微。假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也，脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴也，可与$f{小柴胡汤}。设不了了者，得屎而解。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8gzrPRBPVne', 4, '{"title":"28","description":"<p>159、伤寒五六日，呕而发热者，$n{柴胡汤}证具，而以他药下之，$n{柴胡证}仍在者，复与$n{柴胡汤}，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解。若心下满而鞕痛者，此为结胸也，$f{大陷胸汤}主之，但满而不痛者，此为痞，$u{柴胡}不中与之，宜$f{半夏泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001728,"note":"","videoMemo":"","fangList":["大陷胸汤","半夏泻心汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '159、伤寒五六日，呕而发热者，$n{柴胡汤}证具，而以他药下之，$n{柴胡证}仍在者，复与$n{柴胡汤}，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解。若心下满而鞕痛者，此为结胸也，$f{大陷胸汤}主之，但满而不痛者，此为痞，$u{柴胡}不中与之，宜$f{半夏泻心汤}。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mNqBLla9iNj', 4, '{"title":"29","description":"<p>160、太阳少阳并病，而反下之，成结胸，心下必鞕，若下利不止，水浆不下，其人必烦。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001729,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '160、太阳少阳并病，而反下之，成结胸，心下必鞕，若下利不止，水浆不下，其人必烦。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R7tn3deJZY0', 4, '{"title":"30","description":"<p>161、脉浮而紧，而复下之，紧反入里，则作痞，按之自濡，但气痞耳；$f{小青龙汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001730,"note":"","videoMemo":"","fangList":["小青龙汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '161、脉浮而紧，而复下之，紧反入里，则作痞，按之自濡，但气痞耳；$f{小青龙汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D2rR2hfYlbv', 4, '{"title":"31","description":"<p>162、太阳中风，下利，呕逆，表解者，乃可攻之，若其人絷絷汗出，发作有时，头痛，心下痞满，引胁下痛，干呕短气，汗出不恶寒者，此表解里未和也，$f{十枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001731,"note":"","videoMemo":"","fangList":["十枣汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '162、太阳中风，下利，呕逆，表解者，乃可攻之，若其人絷絷汗出，发作有时，头痛，心下痞满，引胁下痛，干呕短气，汗出不恶寒者，此表解里未和也，$f{十枣汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kbVpVUYuimY', 4, '{"title":"32","description":"<p>163、太阳病，医发汗，遂发热恶寒，因复下之，心下痞，表里俱虚，阴阳气并竭，无阳则阴独，复加烧针，因胸烦，面色青黄，肤瞤者，难治，今色微黄，手足温者易愈。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001732,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '163、太阳病，医发汗，遂发热恶寒，因复下之，心下痞，表里俱虚，阴阳气并竭，无阳则阴独，复加烧针，因胸烦，面色青黄，肤瞤者，难治，今色微黄，手足温者易愈。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XIzQVqPGIGm', 4, '{"title":"33","description":"<p> 164、心下痞，按之濡，其脉关上浮大者，$f{大黄黄连黄芩泻心汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001733,"note":"","videoMemo":"","fangList":["大黄黄连黄芩泻心汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '164、心下痞，按之濡，其脉关上浮大者，$f{大黄黄连黄芩泻心汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('42HQzrVvKzZ', 4, '{"title":"165、心下痞，而复恶寒者，$f{附子泻心汤}主之","description":"<p>165、心下痞，而复恶寒者，$f{附子泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001734,"note":"","videoMemo":"","fangList":["附子泻心汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '165、心下痞，而复恶寒者，$f{附子泻心汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vDtlf0jQxA', 4, '{"title":"166、本以下之，故心下痞，与泻心汤","description":"<p>166、本以下之，故心下痞，与泻心汤。痞不解，其人渴，而口燥烦，小便不利者，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001735,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '166、本以下之，故心下痞，与泻心汤。痞不解，其人渴，而口燥烦，小便不利者，$f{五苓散}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fT07wx3MxIx', 4, '{"title":"36","description":"<p>167、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001736,"note":"","videoMemo":"","fangList":["生姜泻心汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '167、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6yKno40qhs2', 4, '{"title":"37","description":"<p>168、伤寒中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非结热，但以胃中虚，客气上逆，故使鞕也，$f{甘草泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001737,"note":"","videoMemo":"","fangList":["甘草泻心汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '168、伤寒中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非结热，但以胃中虚，客气上逆，故使鞕也，$f{甘草泻心汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7sK9Fot1iXX', 4, '{"title":"38","description":"<p>169、伤寒，服汤药下之，利不止，心下痞鞕，服泻心汤不已，复以他药下之，利益甚，医以理中与之，利仍不止，理中者，理中焦，此利在下焦故也，$f{赤石脂禹余粮汤}主之，复不止者，当利其小便。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001738,"note":"","videoMemo":"","fangList":["赤石脂禹余粮汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '169、伤寒，服汤药下之，利不止，心下痞鞕，服泻心汤不已，复以他药下之，利益甚，医以理中与之，利仍不止，理中者，理中焦，此利在下焦故也，$f{赤石脂禹余粮汤}主之，复不止者，当利其小便。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h1qyewiOsds', 4, '{"title":"39","description":"<p>170、伤寒吐下后，发汗，虚烦，脉甚微，八九日，心下痞鞕，胁下痛，气上冲咽喉，眩冒，经脉动惕者，久而成痿。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001739,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '170、伤寒吐下后，发汗，虚烦，脉甚微，八九日，心下痞鞕，胁下痛，气上冲咽喉，眩冒，经脉动惕者，久而成痿。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TU8hl7VKx5s', 4, '{"title":"40","description":"<p>171、伤寒，发汗，若吐，若下，解后，心下痞鞕，噫气不除者，$f{旋覆代赭汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001740,"note":"","videoMemo":"","fangList":["旋覆代赭汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '171、伤寒，发汗，若吐，若下，解后，心下痞鞕，噫气不除者，$f{旋覆代赭汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('txStksgguqj', 4, '{"title":"41","description":"<p>172、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕，表里不解者，$f{桂枝人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001741,"note":"","videoMemo":"","fangList":["桂枝人参汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '172、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕，表里不解者，$f{桂枝人参汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('789wwofXlE4', 4, '{"title":"42","description":"<p>173、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，后攻其痞，解表宜$f{桂枝汤}；攻痞宜$f{大黄黄连黄芩泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001742,"note":"","videoMemo":"","fangList":["桂枝汤","大黄黄连黄芩泻心汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '173、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，后攻其痞，解表宜$f{桂枝汤}；攻痞宜$f{大黄黄连黄芩泻心汤}。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QckhGdQAJpv', 4, '{"title":"43","description":"<p>174、伤寒发热，汗出不解，心下痞鞕，呕吐而不利者，$f{大柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001743,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '174、伤寒发热，汗出不解，心下痞鞕，呕吐而不利者，$f{大柴胡汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RA5CMl6FlxR', 4, '{"title":"44","description":"<p>175、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001744,"note":"","videoMemo":"","fangList":["瓜蒂散"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '175、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a1J7fVWsYQP', 4, '{"title":"45","description":"<p>176、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此名脏结，死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001745,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '176、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此名脏结，死。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VckEcggY7l3', 4, '{"title":"46","description":"<p>177、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时时恶风，大渴，舌上干燥而烦，欲饮水数升者，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001746,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '177、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时时恶风，大渴，舌上干燥而烦，欲饮水数升者，$f{白虎加人参汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PJTKc7kTPq3', 4, '{"title":"47","description":"<p>178、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001747,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '178、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sx2IdaATZEc', 4, '{"title":"48","description":"<p>179、伤寒，脉浮，发热，无汗，其表不解，当发汗，不可与$f{白虎汤}；渴欲饮，无表证者，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001748,"note":"","videoMemo":"","fangList":["白虎汤","白虎加人参汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '179、伤寒，脉浮，发热，无汗，其表不解，当发汗，不可与$f{白虎汤}；渴欲饮，无表证者，$f{白虎加人参汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NxRFLE6TvNG', 4, '{"title":"49","description":"<p>180、太阳少阳并病，心下鞕，颈项强而眩者，当刺大椎、肺俞、肝俞，慎不可下也，下之则痉。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001749,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '180、太阳少阳并病，心下鞕，颈项强而眩者，当刺大椎、肺俞、肝俞，慎不可下也，下之则痉。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
