INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eC6GD5B36t4', 4, '{"title":"184、伤寒脉结促，心动悸者，$f{炙甘草汤}主之","description":"<p>184、伤寒脉结促，心动悸者，$f{炙甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001753,"note":"","videoMemo":"","fangList":["炙甘草汤"],"bieMing":""}}', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '2024-12-14T07:52:14.000Z', '184、伤寒脉结促，心动悸者，$f{炙甘草汤}主之。', '2024-12-14T07:52:14.000Z', 1, NULL, '5IGM9t76quT', 'section', 'DwPMcet9QLd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TaARI4OQ4z3', 4, '{"title":"1","description":"<p>185、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也？答曰：太阳阳明者，脾约是也，正阳阳明者，胃家实是也；少阳阳明者，发汗，利小便已，胃中燥烦实，大便难是也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '185、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也？答曰：太阳阳明者，脾约是也，正阳阳明者，胃家实是也；少阳阳明者，发汗，利小便已，胃中燥烦实，大便难是也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lgHYwcyqTUr', 4, '{"title":"186、阳明之为病，胃家实是也","description":"<p>186、阳明之为病，胃家实是也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '186、阳明之为病，胃家实是也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FHTxDxLpBSY', 4, '{"title":"3","description":"<p>187、问曰：何缘得阳明病？</p>\n<p></p>\n<p>      答曰：太阳病若发汗，若下，若利小便，此亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '187、问曰：何缘得阳明病？ 答曰：太阳病若发汗，若下，若利小便，此亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V8TX79EOlns', 4, '{"title":"4","description":"<p>188、问曰：阳明病外证云何？答曰：身热，汗自出，不恶寒，反恶热也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '188、问曰：阳明病外证云何？答曰：身热，汗自出，不恶寒，反恶热也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6gkdvDB6ZN6', 4, '{"title":"5","description":"<p>189、问曰：病有得之一日，不发热而恶寒者，何也？</p>\n<p> </p>\n<p>        答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '189、问曰：病有得之一日，不发热而恶寒者，何也？ 答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BuOoj7a1mxm', 4, '{"title":"6","description":"<p>190、问曰：恶寒何故自罢？</p>\n<p></p>\n<p>        答曰：阳明居中，主土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '190、问曰：恶寒何故自罢？ 答曰：阳明居中，主土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2u57v0lqzNR', 4, '{"title":"191、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也","description":"<p>191、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '191、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xSPcJ1p4D4i', 4, '{"title":"8","description":"<p>192、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '192、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T32vD26DCMW', 4, '{"title":"193、伤寒三日，阳明脉大者，此为不传也","description":"<p>193、伤寒三日，阳明脉大者，此为不传也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '193、伤寒三日，阳明脉大者，此为不传也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eyJXfyTb9tB', 4, '{"title":"10","description":"<p>194、伤寒，脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄，若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '194、伤寒，脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄，若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lVSianlLUc9', 4, '{"title":"195、伤寒转属阳明者，其人濈然微汗出也","description":"<p>195、伤寒转属阳明者，其人濈然微汗出也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '195、伤寒转属阳明者，其人濈然微汗出也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P83zBN720u6', 4, '{"title":"12","description":"<p>196、阳明中风，口苦，咽干，腹满，微喘，发热，恶风，脉浮而缓，若下之，则腹满，小便难也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '196、阳明中风，口苦，咽干，腹满，微喘，发热，恶风，脉浮而缓，若下之，则腹满，小便难也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qnKchkGWder', 4, '{"title":"197、阳明病若能食，名中风；不能食，名中寒","description":"<p>197、阳明病若能食，名中风；不能食，名中寒。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '197、阳明病若能食，名中风；不能食，名中寒。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OemGM0NxFnP', 4, '{"title":"14","description":"<p>198、阳明病，若中寒者，不能食，小便不利，手足濈然汗出，此欲作固瘕，必大便初鞕后溏。所以然者，以胃中冷，水谷不别故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '198、阳明病，若中寒者，不能食，小便不利，手足濈然汗出，此欲作固瘕，必大便初鞕后溏。所以然者，以胃中冷，水谷不别故也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1kPbrgBnnZS', 4, '{"title":"15","description":"<p>199、阳明病，初欲食，小便不利，犬便自调，其人骨节疼，翕翕然如有热状，奄然发狂，濈然汗出而解者，此水不胜谷气，与汗共并，脉小则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '199、阳明病，初欲食，小便不利，犬便自调，其人骨节疼，翕翕然如有热状，奄然发狂，濈然汗出而解者，此水不胜谷气，与汗共并，脉小则愈。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dmk4LcP3pks', 4, '{"title":"200、阳明病，欲解时，从申至戌上","description":"<p>200、阳明病，欲解时，从申至戌上。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '200、阳明病，欲解时，从申至戌上。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gkzvxvjfoI0', 4, '{"title":"17","description":"<p>201、阳明病，不能食，攻其热必哕，所以然者，其人本虚，胃中冷故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '201、阳明病，不能食，攻其热必哕，所以然者，其人本虚，胃中冷故也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bGhxCnlqoCR', 4, '{"title":"18","description":"<p>202、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸，虽下之，腹满如故。所以然者，脉迟故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '202、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸，虽下之，腹满如故。所以然者，脉迟故也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7eb1dZN0yd7', 4, '{"title":"19","description":"<p>203、阳明病，法多汗，反无汗，其身如虫行皮中状者，此以久虚故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '203、阳明病，法多汗，反无汗，其身如虫行皮中状者，此以久虚故也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IO5pOh0kthj', 4, '{"title":"20","description":"<p>204、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '204、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('55fyVU0nZnr', 4, '{"title":"21","description":"<p>205、阳明病，但头眩，不恶寒，故能食；若咳者，其人必咽痛；不咳者，咽不痛。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '205、阳明病，但头眩，不恶寒，故能食；若咳者，其人必咽痛；不咳者，咽不痛。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('14Ez40AFH1u', 4, '{"title":"206、阳明病，无汗，小便不利，心中懊憹者，身必发黄","description":"<p>206、阳明病，无汗，小便不利，心中懊憹者，身必发黄。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '206、阳明病，无汗，小便不利，心中懊憹者，身必发黄。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5BabXgO42w6', 4, '{"title":"207、阳明病，被火，额上微汗出，而小便不利者，必发黄","description":"<p>207、阳明病，被火，额上微汗出，而小便不利者，必发黄。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '207、阳明病，被火，额上微汗出，而小便不利者，必发黄。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k3Q5CvBlGPW', 4, '{"title":"24","description":"<p>208、阳明病，脉浮而大者，必潮热，发作有时，但浮者，必自汗出。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '208、阳明病，脉浮而大者，必潮热，发作有时，但浮者，必自汗出。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pGUKgC7LOse', 4, '{"title":"209、阳明病，口燥，但欲漱水，不欲咽者，此必衄","description":"<p>209、阳明病，口燥，但欲漱水，不欲咽者，此必衄。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '209、阳明病，口燥，但欲漱水，不欲咽者，此必衄。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DmdT7AAGQKn', 4, '{"title":"26","description":"<p>210、阳明病，本自汗出，医更重发汗，病已差，尚微烦不了了者，此必大便鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，则知大便不久必出。所以然者，以小便数少，津液当还入胃中，故知不久必大便也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '210、阳明病，本自汗出，医更重发汗，病已差，尚微烦不了了者，此必大便鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，则知大便不久必出。所以然者，以小便数少，津液当还入胃中，故知不久必大便也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a03QR9mYTzl', 4, '{"title":"211、伤寒呕多，虽有阳明证，不可攻之","description":"<p>211、伤寒呕多，虽有阳明证，不可攻之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '211、伤寒呕多，虽有阳明证，不可攻之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s77ZB5DNC2b', 4, '{"title":"28","description":"<p>212、阳明证，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '212、阳明证，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tVgfusCntZ2', 4, '{"title":"29","description":"<p>213、阳明证，眼合色赤，不可攻之，攻之必发热，色黄者，小便不利也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '213、阳明证，眼合色赤，不可攻之，攻之必发热，色黄者，小便不利也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OZiLkqwWEwo', 4, '{"title":"214、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}","description":"<p>214、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018030,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '214、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BXjjAjr4txB', 4, '{"title":"31","description":"<p>215、阳明病，脉实，虽汗出，而不恶热者，其身必重，短气，腹满而喘，有潮热者，此外欲解可攻里也，手足濈然汗出者，此大便已鞕也，$f{大承气汤}主之；若汗多，微发热恶寒者，外未解也，其热不潮者，未可与承气汤；若腹大满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018031,"note":"","videoMemo":"","fangList":["大承气汤","小承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '215、阳明病，脉实，虽汗出，而不恶热者，其身必重，短气，腹满而喘，有潮热者，此外欲解可攻里也，手足濈然汗出者，此大便已鞕也，$f{大承气汤}主之；若汗多，微发热恶寒者，外未解也，其热不潮者，未可与承气汤；若腹大满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3UZMV8bAE5Q', 4, '{"title":"32","description":"<p>216、阳明病潮热，大便微鞕者，可以$f{大承气汤}；不鞕者不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}；汤入腹中，转失气者，此有燥屎也，乃可攻之；若不转失气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕；其后发热者，必大便复鞕而少也，以$f{小承气汤}和之；不转失气者，慎不可攻也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018032,"note":"","videoMemo":"","fangList":["小承气汤","大承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '216、阳明病潮热，大便微鞕者，可以$f{大承气汤}；不鞕者不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}；汤入腹中，转失气者，此有燥屎也，乃可攻之；若不转失气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕；其后发热者，必大便复鞕而少也，以$f{小承气汤}和之；不转失气者，慎不可攻也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vg6JQ78jo6m', 4, '{"title":"33","description":"<p>217、阳明病，实则谵语，虚则郑声，郑声者重语也，直视，谵浯，喘满者，死；下利者，亦死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '217、阳明病，实则谵语，虚则郑声，郑声者重语也，直视，谵浯，喘满者，死；下利者，亦死。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tQGd0GTbh4X', 4, '{"title":"34","description":"<p>218、阳明病，发汗多，若重发汗，以亡其阳，谵语，脉短者，死；脉自和者，不死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '218、阳明病，发汗多，若重发汗，以亡其阳，谵语，脉短者，死；脉自和者，不死。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KzZ5gqzpcgI', 4, '{"title":"35","description":"<p>219、伤寒，若吐，若下后，不解，不大便五六日，上至十余日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死；微者，但发热，谵语者，$f{大承气汤}主之</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018035,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '219、伤寒，若吐，若下后，不解，不大便五六日，上至十余日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死；微者，但发热，谵语者，$f{大承气汤}主之', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pYRmzO8jJkY', 4, '{"title":"36","description":"<p>220、阳明病，其人多汗，以津夜外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018036,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '220、阳明病，其人多汗，以津夜外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TrosKNlI5WE', 4, '{"title":"37","description":"<p>221、阳明病，谵语，发热潮，脉滑而疾者，$f{小承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018037,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '221、阳明病，谵语，发热潮，脉滑而疾者，$f{小承气汤}主之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('juFeNXW4a3v', 4, '{"title":"38","description":"<p>222、阳明病，服$n{承气汤}后，不转失气，明日又不大便，脉反微涩者，里虚也，为难治，不可更与$n{承气汤}也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '222、阳明病，服$n{承气汤}后，不转失气，明日又不大便，脉反微涩者，里虚也，为难治，不可更与$n{承气汤}也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8b0qZOhExaO', 4, '{"title":"39","description":"<p>223、阳明病，谵语，有潮热，反不能食者，胃中必有燥屎五六枚也，若能食者，但鞕尔，宜$f{大承气汤}下之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018039,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '223、阳明病，谵语，有潮热，反不能食者，胃中必有燥屎五六枚也，若能食者，但鞕尔，宜$f{大承气汤}下之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aamW6s8T5I3', 4, '{"title":"40","description":"<p>224、阳明病，下血，谵语者，此为热入血室，但头汗出者，刺期门，随其实而泻之，濈然汗出则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018040,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '224、阳明病，下血，谵语者，此为热入血室，但头汗出者，刺期门，随其实而泻之，濈然汗出则愈。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GPB5QNJZLm8', 4, '{"title":"41","description":"<p>225、阳明病，汗出，谵语者，以有燥屎在胃中，此为实也，须过经乃可下之；下之若早，语言必乱，以表虚里实故也，下之宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018041,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '225、阳明病，汗出，谵语者，以有燥屎在胃中，此为实也，须过经乃可下之；下之若早，语言必乱，以表虚里实故也，下之宜$f{大承气汤}。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SCZf9a2mLwq', 4, '{"title":"42","description":"<p>226、伤寒四五日，脉沉而喘满，沉为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018042,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '226、伤寒四五日，脉沉而喘满，沉为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0nEuUaVLj5P', 4, '{"title":"43","description":"<p>227、三阳合病，腹满，身重，难以转侧，口不仁面垢，若发汗则谵语，遗尿，下之，则手足逆冷，额上出汗，若自汗者，宜$f{白虎汤}。自利者，宜$f{葛根黄连黄芩甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018043,"note":"","videoMemo":"","fangList":["白虎汤","葛根黄连黄芩甘草汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '227、三阳合病，腹满，身重，难以转侧，口不仁面垢，若发汗则谵语，遗尿，下之，则手足逆冷，额上出汗，若自汗者，宜$f{白虎汤}。自利者，宜$f{葛根黄连黄芩甘草汤}。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Qs7X2Fxt0t2', 4, '{"title":"44","description":"<p>228、二阳并病，太阳证罢，但发潮热，手足絷絷汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018044,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '228、二阳并病，太阳证罢，但发潮热，手足絷絷汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7hERexcpun5', 4, '{"title":"45","description":"<p>229、阳明病，脉浮而大，咽燥口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重；若发汗，则躁，心愦愦反谵语；若加温针，必怵惕，烦躁，不得眠；若下之，则胃中空虚，客气动膈，心中懊憹，舌上苔者，$f{栀子豉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018045,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '229、阳明病，脉浮而大，咽燥口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重；若发汗，则躁，心愦愦反谵语；若加温针，必怵惕，烦躁，不得眠；若下之，则胃中空虚，客气动膈，心中懊憹，舌上苔者，$f{栀子豉汤}主之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wwpHGXyOZzm', 4, '{"title":"46","description":"<p>230、阳明病，渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018046,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '230、阳明病，渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
