INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('beIGq6b52Oq', 4, '{"title":"53","description":"<p>237、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，与$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018053,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '237、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，与$f{小柴胡汤}。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FcK6I5RI5vd', 4, '{"title":"54","description":"<p>238、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然汗出而解也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018054,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '238、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然汗出而解也。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hEgzdkhbGBX', 4, '{"title":"55","description":"<p>239、阳明中风，脉弦浮大，而短气，腹都满，胁下及心痛，久按之气不通，鼻干不得涕，嗜卧，一身及目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之小差，外不解，病过十日，脉续浮者，与$f{小柴胡汤}；脉但浮，无余证者，与麻黄汤；若不尿，腹满加哕者，不治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018055,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '239、阳明中风，脉弦浮大，而短气，腹都满，胁下及心痛，久按之气不通，鼻干不得涕，嗜卧，一身及目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之小差，外不解，病过十日，脉续浮者，与$f{小柴胡汤}；脉但浮，无余证者，与麻黄汤；若不尿，腹满加哕者，不治。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KQYkJxcnwLW', 4, '{"title":"56","description":"<p>240、动作头痛，短气，有潮热者，属阳明也，$f{白蜜煎}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018056,"note":"","videoMemo":"","fangList":["白蜜煎"],"bieMing":""}}', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '2024-12-14T09:26:51.000Z', '240、动作头痛，短气，有潮热者，属阳明也，$f{白蜜煎}主之。', '2024-12-14T09:26:51.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i25tUNNRUNq', 4, '{"title":"57","description":"<p>241、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，便虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$n{王瓜根}，及$f{大猪胆汁}，皆可为导。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018057,"note":"","videoMemo":"","fangList":["蜜煎导","大猪胆汁"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '241、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，便虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$n{王瓜根}，及$f{大猪胆汁}，皆可为导。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3kzlMk5inY0', 4, '{"title":"58","description":"<p>242、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018058,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '242、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('24hQf44sr5D', 4, '{"title":"59","description":"<p>243、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018059,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '243、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oKMB7psNZzj', 4, '{"title":"60","description":"<p>244、阳明病，发热汗出者，此为热越，不能发黄也，但头汗出，身无汗，剂颈而还，小便不利，渴引水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018060,"note":"","videoMemo":"","fangList":["茵陈蒿汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '244、阳明病，发热汗出者，此为热越，不能发黄也，但头汗出，身无汗，剂颈而还，小便不利，渴引水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gciwRD4YLFa', 4, '{"title":"61","description":"<p>245、阳明病，其人善忘者，必有蓄血，所以然者，本有久瘀血，故令善忘，屎虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018061,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '245、阳明病，其人善忘者，必有蓄血，所以然者，本有久瘀血，故令善忘，屎虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I4TansWsdLH', 4, '{"title":"62","description":"<p>246、阳明病，下之，心中懊憹而烦，胃中有燥屎者，可攻；腹微满，大便初鞕后溏者，不可攻之，若有燥屎者宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018062,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '246、阳明病，下之，心中懊憹而烦，胃中有燥屎者，可攻；腹微满，大便初鞕后溏者，不可攻之，若有燥屎者宜$f{大承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
